local config = {
  ui_story_5034_50340000_1_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5034_50340000_2_dialog_content = "Oh tidak! Apakah kamu baik-baik saja?",
  ui_story_5034_50340000_3_dialog_content = "aku baik-baik saja...",
  ui_story_5034_50340000_4_dialog_content = "Hah? Itu kamu, Tn. Navigator!",
  ui_story_5034_50340000_5_dialog_content = "Halo, <color=#FFB400>Schewe</color>.",
  ui_story_5034_50340000_6_dialog_content = "Anda tahu Anda bisa memanggil saya dengan nama saya, bukan? Seperti yang dilakukan Nekoyashiki dan yang lainnya.",
  ui_story_5034_50340000_7_dialog_content = "Apa? Tidak mungkin!",
  ui_story_5034_50340000_8_dialog_content = "Anda lebih tua dari saya, dan saya harus menghormati senior saya!",
  ui_story_5034_50340000_9_dialog_content = "Er... Oke, kalau begitu.",
  ui_story_5034_50340000_10_dialog_content = "Apa yang Anda pikirkan tentang permen? Apakah rasanya enak?",
  ui_story_5034_50340000_11_dialog_content = "T-Tentu saja! Itu benar-benar nikmat!",
  ui_story_5034_50340000_12_dialog_content = "Ini permen favorit kami! Terima kasih, Tuan Navigator!",
  ui_story_5034_50340000_13_dialog_content = "Schewe berbohong! Dia tidak memakannya sama sekali!",
  ui_story_5034_50340000_14_dialog_content = "Latan! Tuan Navigator dan saya sedang berbicara, pergi!",
  ui_story_5034_50340000_15_dialog_content = "Tapi kau berbohong, Schewe! Anda memberikan permen itu kepada saya ...",
  ui_story_5034_50340000_16_dialog_content = "Ingat apa yang dikatakan Pollux kepada kami? Kita seharusnya tidak berbohong kepada orang-orang yang baik kepada kita!",
  ui_story_5034_50340000_17_dialog_content = "Saya tidak bermaksud berbohong, sekarang keluar!",
  ui_story_5034_50340000_18_dialog_content = "Schewe... Apakah kamu meminta permen itu agar kamu bisa membuat Latan merasa lebih baik?",
  ui_story_5034_50340000_19_dialog_content = "Kurasa tidak ada yang bisa melewatimu, Tn. Navigator. Maaf, seharusnya aku tidak berbohong sejak awal.",
  ui_story_5034_50340000_20_dialog_content = "Tuan Navigator? Saya benar-benar ingin Schewe memiliki permen juga.",
  ui_story_5034_50340000_21_dialog_content = "Jika saya tahu hanya ada satu potong, saya tidak akan memakan semuanya dalam satu gigitan...",
  ui_story_5034_50340000_22_dialog_content = "Jangan repot-repot, Latan. Aku baik-baik saja tanpa.",
  ui_story_5034_50340000_23_dialog_content = "Hanya melihatmu kembali ke dirimu yang dulu membuatku merasa lebih bahagia daripada makan permen apa pun!",
  ui_story_5034_50340000_24_dialog_content = "Baiklah, anak-anak. Itu akan dilakukan untuk saat ini.",
  ui_story_5034_50340000_25_dialog_content = "Ini hanya beberapa permen, kau tahu? Membeli permen bukanlah masalah besar bagi orang dewasa seperti saya.",
  ui_story_5034_50340000_26_dialog_content = "Tapi hanya Nekoyashiki yang memiliki permen seperti itu... Kita tidak bisa menemukannya di Euphoria sama sekali.",
  ui_story_5034_50340000_27_dialog_content = "Jika Nekoyashiki bisa mendapatkannya entah bagaimana, lalu mengapa saya tidak? Beri aku kredit, teman-teman!",
  ui_story_5034_50340000_28_dialog_content = "Tunggu saja, aku akan membawakanmu kembali begitu banyak permen sehingga kamu tidak akan bisa menghabiskan semuanya!",
  ui_story_5034_50340000_29_dialog_content = "Ya! Anda yang terbaik, Tn. Navigator! Tidak ada yang lebih baik dari Anda!",
  ui_story_5034_50340000_30_dialog_content = "Hei, Latan, jangan katakan itu...",
  ui_story_5034_50340000_31_dialog_content = "Bagaimana jika Mr Navigator tidak dapat menemukan permen?",
  ui_story_5034_50340000_32_dialog_content = "Terima kasih atas kepercayaannya, Schewe...",
  ui_story_5034_50340000_33_dialog_content = "Bagaimanapun, orang dewasa harus selalu menepati janjinya kepada anak-anak. Kalian berdua tunggu saja di sini untukku, dan aku akan segera kembali.",
  ui_story_5034_50340000_34_dialog_content = "(Sekarang kemana saya harus pergi untuk mencari permen itu...?)",
  ui_story_5034_50340000_35_dialog_content = "(Oh, ya! Saya yakin dia punya ide!)",
  ui_story_5034_50340000_36_dialog_content = "Hmm? Sudah merasa istirahat, ya?",
  ui_story_5034_50340000_37_dialog_content = "Tentu saja! Saya merasa baik-baik saja sekarang.",
  ui_story_5034_50340000_38_dialog_content = "Omong-omong, Pollux... Ada yang ingin kutanyakan padamu.",
  ui_story_5034_50340000_39_dialog_content = "Apakah Anda tahu di mana saya dapat menemukan lebih banyak permen yang disukai anak-anak?",
  ui_story_5034_50340000_40_dialog_content = "Anda berbicara tentang permen yang biasanya dibawa Nekoyashiki, ya?",
  ui_story_5034_50340000_41_dialog_content = "Saya belum pernah melihatnya di mana pun di Euphoria, yang berarti dia pasti membawanya dari tempat lain.",
  ui_story_5034_50340000_42_dialog_content = "Tapi kenapa kamu tidak pergi dan bertanya sendiri padanya? Saya rasa dia belum pergi.",
  ui_story_5034_50340000_43_option_content = "Tidak ada kesempatan!",
  ui_story_5034_50340000_44_dialog_content = "Selain itu, itu hanya permen. Jika dia bisa menguasainya, maka saya juga bisa.",
  ui_story_5034_50340000_45_dialog_content = "Selama dia tidak membuatnya sendiri, aku yakin aku bisa menemukan cara untuk membelinya!",
  ui_story_5034_50340000_46_option_content = "Sepertinya aku tidak punya pilihan selain bertanya padanya...",
  ui_story_5034_50340000_47_dialog_content = "Apakah benar-benar tidak ada cara lain...?",
  ui_story_5034_50340000_48_dialog_content = "Terima kasih, Pollux.",
  ui_story_5034_50340000_49_dialog_content = "Tunggu, PlayerName. Saya baru ingat sebuah toko tertentu di kota yang telah menjalankan bisnis untuk waktu yang sangat lama.",
  ui_story_5034_50340000_50_dialog_content = "Penjaga toko cukup paham bisnis dan membawa semua jenis barang eksotis untuk dijual di sini di Euphoria.",
  ui_story_5034_50340000_51_dialog_content = "Anda mungkin ingin mencoba keberuntungan Anda di sana terlebih dahulu.",
  ui_story_5034_50340000_52_dialog_content = "Mengerti! Terima kasih sekali lagi, Pollux!",
  ui_story_5034_50340000_53_dialog_content = "Hai! Aku masih belum memberitahumu di mana tokonya!",
  ui_story_5034_50340000_54_dialog_content = "Selalu terburu-buru...",
  ui_story_5034_50340000_55_dialog_content = "Koraks! Dimana kamu, Corax?",
  ui_story_5034_50340000_56_dialog_content = "Tepat di belakangmu... Ada apa dengan semua teriakan itu?",
  ui_story_5034_50340000_57_dialog_content = "Ahhh! Jangan menyergapku seperti itu!",
  ui_story_5034_50340000_58_dialog_content = "Lagi pula, Anda punya waktu sebentar, Corax?",
  ui_story_5034_50340000_59_dialog_content = "Kenapa tanya begitu?",
  ui_story_5034_50340000_60_dialog_content = "Saya ingin membeli permen, tetapi toko yang menjualnya ada di kota, dan saya tidak ingin pergi sendiri ...",
  ui_story_5034_50340000_61_dialog_content = "Tidak dapat membantu Anda. Saya akan pergi ke suatu tempat yang bagus dan kosong untuk memberi makan burung-burung.",
  ui_story_5034_50340000_62_dialog_content = "Hah? Apakah saya benar-benar kurang penting daripada sepasang burung?",
  ui_story_5034_50340000_63_dialog_content = "Oh, hai, Nekoyashiki. Anda tepat waktu.",
  ui_story_5034_50340000_64_dialog_content = "PlayerName ingin pergi ke kota untuk membeli permen. Pergi dengan dia, kan? Saya tidak punya waktu untuk itu.",
  ui_story_5034_50340000_65_dialog_content = "Koraks...",
  ui_story_5034_50340000_66_dialog_content = "Ah... Permen, katamu?",
  ui_story_5034_50340000_67_dialog_content = "Jadi permen yang kuberikan padamu sebelumnya... Kau memakannya sendiri daripada memberikannya pada anak-anak, bukan?",
  ui_story_5034_50340000_68_dialog_content = "Tidak tahu bahwa Anda adalah orang seperti itu, PlayerName...",
  ui_story_5034_50340000_69_dialog_content = "Jangan biarkan imajinasi Anda menjadi liar! Saya hanya ingin membeli lebih banyak untuk anak-anak, itu saja.",
  ui_story_5034_50340000_70_dialog_content = "Tapi karena Anda sudah di sini, itu menyelamatkan saya dari kesulitan pergi ke kota.",
  ui_story_5034_50340000_71_dialog_content = "Jika Anda memiliki lebih banyak permen itu, mengapa Anda tidak menjual semuanya kepada saya?",
  ui_story_5034_50340000_72_dialog_content = "Saya akan senang untuk membantu Anda terlihat keren di depan anak-anak, PlayerName...",
  ui_story_5034_50340000_73_dialog_content = "Tapi sayangnya, saya sudah membagikan atau memakan sisa permennya.",
  ui_story_5034_50340000_74_dialog_content = "Bagian yang kuberikan padamu kebetulan adalah yang terakhir.",
  ui_story_5034_50340000_75_dialog_content = "Sungguh... Sepertinya aku harus mencoba peruntunganku di toko itu, bagaimanapun juga...",
  ui_story_5034_50340000_76_dialog_content = "\"Toko itu\"?",
  ui_story_5034_50340000_77_dialog_content = "Saya tidak tahu ada toko di Euphoria yang menyediakan permen semacam ini ... Sekarang saya sangat penasaran untuk melihatnya sendiri.",
  ui_story_5034_50340000_78_dialog_content = "Saya bertanya kepada Pollux, dan dia memberi tahu saya tentang sebuah toko di kota yang mengimpor semua jenis barang eksotis. Saya akan melihat apakah saya dapat menemukannya di sana.",
  ui_story_5034_50340000_79_dialog_content = "<size=30>Ah... toko itu...</size>",
  ui_story_5034_50340000_80_dialog_content = "Sial, tunggu sebentar... Aku benar-benar lupa menanyakan Pollux di mana itu.",
  ui_story_5034_50340000_81_dialog_content = "Aku ingin tahu apakah dia masih di pintu masuk...",
  ui_story_5034_50340000_82_dialog_content = "Aku tahu di mana itu. Ayo, aku akan membawamu ke sana.",
  ui_story_5034_50340000_83_dialog_content = "Apa...? Anda akan dengan saya?",
  ui_story_5034_50340000_84_dialog_content = "Saya hanya ingin tahu apakah penjaga toko memiliki apa yang diperlukan untuk mendapatkan permen semacam ini, itu saja.",
  ui_story_5034_50340000_85_dialog_content = "Kami hanya kebetulan menuju ke arah yang sama.",
  ui_story_5034_50340000_86_dialog_content = "Sekarang cepatlah, atau aku akan pergi sendiri.",
  ui_story_5034_50340000_87_dialog_content = "Hai! Tunggu aku!",
  ui_story_5034_50340101_1_dialog_content = "Kita harus segera sampai, kan? Rasanya seperti kita telah berjalan selamanya...",
  ui_story_5034_50340101_2_dialog_content = "Ya... Jika saya tidak salah, maka ini adalah toko yang Pollux bicarakan.",
  ui_story_5034_50340101_3_dialog_content = "Ayo, mari kita masuk dan melihat-lihat.",
  ui_story_5034_50340101_4_dialog_content = "Nah, jika bukan Nekoyashiki... Untuk apa aku berhutang kesenangan dari pelanggan langka seperti itu?",
  ui_story_5034_50340101_5_dialog_content = "Saya tidak pernah berpikir toko sederhana seperti saya bisa membawa sesuatu yang menarik untuk orang seperti Anda.",
  ui_story_5034_50340101_6_dialog_content = "Oh, jangan pedulikan aku, aku hanya melihat-lihat... Dia, di sisi lain, tertarik untuk membeli sesuatu.",
  ui_story_5034_50340101_7_dialog_content = "Maaf, tapi apakah Anda kebetulan menjual permen di sini?",
  ui_story_5034_50340101_8_dialog_content = "Anda harus mencarinya sendiri. Juga, kami tidak menjual apa pun secara kredit, jadi jangan repot-repot bertanya.",
  ui_story_5034_50340101_9_dialog_content = "Seseorang bangun di sisi tempat tidur yang salah...",
  ui_story_5034_50340101_10_dialog_content = "Tidak apa-apa, saya tidak keberatan mencari sendiri.",
  ui_story_5034_50340101_11_dialog_content = "Ah! Menemukannya! Saya tidak percaya itu benar-benar ada di sini!",
  ui_story_5034_50340101_12_dialog_content = "Hm? Biarkan saya melihat itu...",
  ui_story_5034_50340101_13_dialog_content = "Oh? Katakanlah, penjaga toko... Dari mana tepatnya Anda mengimpor ini?",
  ui_story_5034_50340101_14_dialog_content = "Mencoba memeras saya keluar dari bisnis, eh? Anda sudah memiliki banyak saluran untuk barang-barang Anda, jadi saya tidak perlu memberi tahu Anda tentang barang saya, terima kasih banyak.",
  ui_story_5034_50340101_15_dialog_content = "Menjalankan bahkan toko kecil seperti milikku tidaklah mudah, kau tahu? Cobalah untuk memikirkan orang-orang kecil sesekali, \"Tuan\" Nekoyashiki.",
  ui_story_5034_50340101_16_dialog_content = "Jika bisnis sangat sulit, mengapa Anda mengimpor permen yang tidak populer seperti ini? Apakah Anda tidak khawatir kehilangan keuntungan Anda?",
  ui_story_5034_50340101_17_dialog_content = "Saya perhatikan bahwa anak-anak di sini menyukai permen ini. Jika saya tidak bisa menjualnya, saya akan memberikannya kepada anak-anak.",
  ui_story_5034_50340101_18_dialog_content = "Oh, begitu…",
  ui_story_5034_50340101_19_dialog_content = "Apakah Anda akan melihat itu? Kurasa bukan hanya kau yang membawa permen seperti itu sekarang, ya?",
  ui_story_5034_50340101_20_dialog_content = "Tampaknya begitu... Yah, selamat, saya kira.",
  ui_story_5034_50340101_21_dialog_content = "Saya akan mengambil semuanya, Pak!",
  ui_story_5034_50340101_22_dialog_content = "Megah! Nah, harganya 3.000 Nightium per kantong, dengan total...",
  ui_story_5034_50340101_23_dialog_content = "Tunggu sebentar! Apakah Anda mengatakan 3.000 Nightium per kantong?!",
  ui_story_5034_50340101_24_dialog_content = "*Tertawa*",
  ui_story_5034_50340101_25_dialog_content = "Kenapa ya, itu yang saya katakan. Setiap kantong permen khusus ini berharga 3.000 Nightium.",
  ui_story_5034_50340101_26_dialog_content = "Tetapi jika Anda membeli semua stok saya, saya akan memasukkan tas jinjing besar untuk Anda bawa pulang.",
  ui_story_5034_50340101_27_dialog_content = "Tapi bagaimana bisa satu kantong permen berharga 3.000 Nightium, untuk memulai?",
  ui_story_5034_50340101_28_dialog_content = "Nekoyashiki, seberapa kaya kamu?!",
  ui_story_5034_50340101_29_dialog_content = "Saya tidak pernah mengatakan saya membeli permen saya di sini.",
  ui_story_5034_50340101_30_dialog_content = "Jadi apa yang Anda katakan... adalah bahwa orang ini menipu saya, kan?",
  ui_story_5034_50340101_31_dialog_content = "Euforia tidak memiliki sarana untuk menghasilkan permen, antara lain. Sebagian besar produk diimpor ke sini melalui jalur perdagangan yang sudah mapan.",
  ui_story_5034_50340101_32_dialog_content = "Akibatnya, sebagian besar barang yang Anda temukan untuk dijual di sini lebih mahal daripada di tempat lain.",
  ui_story_5034_50340101_33_dialog_content = "Apakah Anda memberi tahu saya 3.000 Nightium untuk sekantong permen yang sangat sedikit dapat Anda terima?!",
  ui_story_5034_50340101_34_dialog_content = "Bukan itu yang saya katakan. Saya hanya memberi Anda beberapa informasi latar belakang sehingga Anda akan merasa lebih baik saat melakukan pembelian.",
  ui_story_5034_50340101_35_dialog_content = "<size=45>Itu tidak membantu sama sekali.</size>",
  ui_story_5034_50340101_36_dialog_content = "Anda dipersilakan untuk membeli sekantong permen, jika Anda mau? Memang, tas jinjing akan keluar dari pertanyaan ...",
  ui_story_5034_50340101_37_dialog_content = "(Kurasa aku tidak punya pilihan. Lagipula aku berjanji pada anak-anak... 3.000 Nightium sekantong, aku harus mampu membeli setidaknya satu... Benar?)",
  ui_story_5034_50340101_38_dialog_content = "Aku... Aku hanya punya 150 Nightium.",
  ui_story_5034_50340101_39_dialog_content = "Jangan lihat saya, saya membawa kepala saya ketika saya meninggalkan rumah, bukan uang saya.",
  ui_story_5034_50340101_40_dialog_content = "Kalau saja kita berada di Umbraton... Aku bisa mendapatkan setidaknya lima kantong permen seharga 150 Nightium!",
  ui_story_5034_50340101_41_dialog_content = "Tidak ada seorang pun di sini yang melakukan sesuatu tentang harga selangit ini?",
  ui_story_5034_50340101_42_dialog_content = "Tapi kita tidak di Umbraton, kan? Kami berada di Euphoria, jadi Anda harus bermain sesuai aturan Euphoria.",
  ui_story_5034_50340101_43_dialog_content = "Dan jangan lupa, Sobat, kami tidak menjual apapun secara kredit di toko ini.",
  ui_story_5034_50340101_44_dialog_content = "Jika Anda tidak membeli apa pun, saya akan mengembalikan barang ini ke rak.",
  ui_story_5034_50340101_45_dialog_content = "(Jika saya tidak menemukan cara untuk mengembalikan permen ini, Schewe dan Latan akan sangat kecewa.)",
  ui_story_5034_50340101_46_dialog_content = "(Dan setelah semua yang saya katakan juga...)",
  ui_story_5034_50340101_47_dialog_content = "Saya ingin membeli tas, Pak... Tapi saya benar-benar tidak punya cukup uang.",
  ui_story_5034_50340101_48_dialog_content = "Mungkin saya bisa menukar sesuatu dengan tas?",
  ui_story_5034_50340101_49_dialog_content = "Begitu... Yah, aku tidak ingin menolak teman Nekoyashiki dengan kasar.",
  ui_story_5034_50340101_50_dialog_content = "Bagaimana dengan ini? Mengapa Anda tidak tinggal sebentar dan bekerja untuk saya, dan saya akan memberi Anda sekantong permen itu sebagai pembayaran atas bantuan Anda? Apakah itu terdengar adil?",
  ui_story_5034_50340101_51_dialog_content = "Kedengarannya seperti kesepakatan! Jadi apa sebenarnya yang Anda perlu saya lakukan?",
  ui_story_5034_50340101_52_dialog_content = "Saya tidak bisa mengatakan bahwa saya memiliki banyak pengalaman kerja, tetapi saya berjanji bahwa saya adalah salah satu yang terbaik di Astra.",
  ui_story_5034_50340101_53_dialog_content = "Aku harus pergi sekarang. Semoga berhasil, <color=#FFB400>pekerja paruh waktu</color>.",
  ui_story_5034_50340102_1_dialog_content = "(Pada saat saya akhirnya melihat jam, seluruh pagi hampir berlalu.)",
  ui_story_5034_50340102_2_dialog_content = "(Menyimpan dan mengatur rak, menyapu toko... Dia bahkan ingin aku memikat pelanggan.)",
  ui_story_5034_50340102_3_dialog_content = "(Tapi siapa yang mau berbelanja di toko dengan harga gila-gilaan seperti itu?)",
  ui_story_5034_50340102_4_dialog_content = "Nah, anak muda?",
  ui_story_5034_50340102_5_dialog_content = "Sekarang Anda tahu betapa sulitnya menjalankan toko di Euphoria.",
  ui_story_5034_50340102_6_dialog_content = "Meski begitu, aku tidak ingin mempersulit teman Nekoyashiki...",
  ui_story_5034_50340102_7_dialog_content = "(Apakah Anda bercanda? Saya cukup yakin Anda melakukan ini TEPAT karena saya mengenalnya!)",
  ui_story_5034_50340102_8_dialog_content = "(Tak perlu dikatakan lagi, tapi saya tidak akan pernah kembali ke toko ini lagi!)",
  ui_story_5034_50340102_9_dialog_content = "Di sinilah Anda, kemudian, satu kantong permen sebagai pembayaran atas kerja keras Anda.",
  ui_story_5034_50340102_10_dialog_content = "Saya tidak yakin apakah saya harus berterima kasih atau tidak ...",
  ui_story_5034_50340102_11_dialog_content = "Tidak, terima kasih diperlukan... Tapi coba ingat untuk membawa lebih banyak uang lain kali.",
  ui_story_5034_50340102_12_dialog_content = "Oh, Anda tidak perlu khawatir tentang itu ... pasti tidak akan ada waktu berikutnya!",
  ui_story_5034_50340102_13_dialog_content = "Bagaimanapun, setidaknya saya mendapatkan permennya.",
  ui_story_5034_50340102_14_dialog_content = "Ini hanya satu tas, tapi aku mendapatkannya. Sekarang Schewe juga bisa menikmatinya!",
  ui_story_5034_50340102_15_dialog_content = "Hmm? Tunggu sebentar, ada sesuatu yang tercetak di tasnya...",
  ui_story_5034_50340102_16_dialog_content = "\"Diproduksi oleh Spesialisasi Timur Jauh di Umbraton...\"",
  ui_story_5034_50340102_17_dialog_content = "\"Harga Eceran yang Disarankan: 30 Nightium...\"",
  ui_story_5034_50340102_18_dialog_content = "<size=45>Apa?!</size>",
  ui_story_5034_50340102_19_dialog_content = "Aku bekerja keras sepanjang pagi untuk membeli 3.000 kantong permen Nightium, tapi setelah semua itu...",
  ui_story_5034_50340102_20_dialog_content = "<size=45>Selama ini hanya permen Umbraton yang murah?!</size>",
  ui_story_5034_50340102_21_dialog_content = "Apakah Anda akan melihat itu? Kurasa bukan hanya kau yang membawa permen seperti itu sekarang, ya?",
  ui_story_5034_50340102_22_dialog_content = "Tampaknya begitu... Yah, selamat, saya kira.",
  ui_story_5034_50340102_23_dialog_content = "Dia tahu! Dia tahu, namun dia tidak repot-repot memberitahuku!",
  ui_story_5034_50340102_24_dialog_content = "<color=#e8d9bb>*Menggerutu*</color>",
  ui_story_5034_50340102_25_dialog_content = "Ugh... Aku kelaparan setelah semua kerja keras itu...",
  ui_story_5034_50340102_26_dialog_content = "Ini hampir tengah hari. Jika saya bergegas kembali, saya harus bisa tepat waktu untuk makan siang bersama anak-anak.",
  ui_story_5034_50340102_27_dialog_content = "Aku akan membiarkan penjaga toko bengkok itu lolos untuk saat ini... Memberikan permen ini kepada anak-anak jauh lebih penting sekarang.",
  ui_story_5034_50340102_28_dialog_content = "Tapi perhatikan kata-kataku, lain kali aku melihatnya... Aku akan memberinya sedikit pelajaran tentang perdagangan yang adil!",
  ui_story_5034_50340102_29_dialog_content = "Lihat, Schewe! Tuan Navigator benar-benar berhasil menemukan beberapa permen itu!",
  ui_story_5034_50340102_30_dialog_content = "Anda akan dapat mencoba beberapa juga!",
  ui_story_5034_50340102_31_dialog_content = "Tapi dia bekerja keras sepanjang pagi untuk permen itu...",
  ui_story_5034_50340102_32_dialog_content = "Itu benar... Kami mengikuti Pak Navigator karena kami ingin melihat dari mana dia mendapatkan permen itu.",
  ui_story_5034_50340102_33_dialog_content = "Dia bilang dia akan membelikan kita banyak juga...",
  ui_story_5034_50340102_34_dialog_content = "Aku tahu dia tidak sungguh-sungguh.",
  ui_story_5034_50340102_35_dialog_content = "Tapi kalau saja kita tidak tampak begitu putus asa untuk makan permen...",
  ui_story_5034_50340102_36_dialog_content = "Dia tidak perlu bekerja untuk penjaga toko yang kejam itu hanya untuk membelinya untuk kita.",
  ui_story_5034_50340102_37_dialog_content = "Aku salah, Latan... Aku tidak pantas makan permen...",
  ui_story_5034_50340102_38_dialog_content = "Schewe...",
  ui_story_5034_50340102_39_dialog_content = "Tunggu! Saya punya ide!",
  ui_story_5034_50340102_40_dialog_content = "Sebuah ide...?",
  ui_story_5034_50340102_41_dialog_content = "Jika Tuan Navigator bisa bekerja di toko itu, maka kita juga bisa!",
  ui_story_5034_50340102_42_dialog_content = "Maksudmu kita bisa bekerja untuk permen juga?",
  ui_story_5034_50340102_43_dialog_content = "Betul sekali! Dengan begitu, Tn. Navigator tidak akan berpikir kita hanyalah sepasang anak yang egois!",
  ui_story_5034_50340102_44_dialog_content = "Kita tidak bisa hanya tinggal di sini dan menunggu dia membawakan permen untuk kita.",
  ui_story_5034_50340102_45_dialog_content = "Dia juga berhak menikmati hasil kerja keras kita!",
  ui_story_5034_50340102_46_dialog_content = "Dan dengan kami berdua, kami seharusnya bisa mendapatkan dua tas, bukan satu! Tapi apa yang harus kita lakukan dengan tas kedua?",
  ui_story_5034_50340102_47_dialog_content = "Mengapa tidak memberikannya kepada Pollux sebagai hadiah? Dia bekerja keras untuk menjaga kita juga... Kita harus menunjukkan rasa terima kasih kita padanya!",
  ui_story_5034_50340102_48_dialog_content = "Kemudian diselesaikan! Adapun pembenci permen itu, Casta... Haruskah kita menggunakan <color=#FFB400>trik biasa</color> kita?",
  ui_story_5034_50340102_49_dialog_content = "Yah, ini tidak akan mudah, Latan.",
  ui_story_5034_50340102_50_dialog_content = "Saya tahu! Serahkan saja padaku!",
  ui_story_5034_50340201_1_dialog_content = "Oh, kau kembali.",
  ui_story_5034_50340201_2_dialog_content = "Saya pikir Anda pergi keluar hanya untuk mendapatkan permen? Mengapa Anda begitu berkeringat?",
  ui_story_5034_50340201_3_dialog_content = "\"Hanya untuk mendapatkan permen,\" pantatku ...",
  ui_story_5034_50340201_4_dialog_content = "Pernahkah Anda melihat Nekoyashiki? Saya perlu \"berterima kasih\" padanya dengan benar karena telah membantu saya.",
  ui_story_5034_50340201_5_dialog_content = "Aku belum melihatnya di sekitar sini. Bukankah kalian berdua pergi bersama?",
  ui_story_5034_50340201_6_dialog_content = "<color=#e8d9bb>*Menggerutu*</color>",
  ui_story_5034_50340201_7_dialog_content = "Ah... Sangat lapar... Kurasa aku akan membiarkannya untuk saat ini.",
  ui_story_5034_50340201_8_dialog_content = "Apakah makan siang sudah siap? Apa yang kita alami hari ini?",
  ui_story_5034_50340201_9_dialog_content = "Maaf, tapi semua orang selesai makan siang beberapa waktu lalu.",
  ui_story_5034_50340201_10_dialog_content = "Apa?! Dan tidak ada yang berpikir untuk meninggalkan beberapa untukku?!",
  ui_story_5034_50340201_11_dialog_content = "Anda memiliki sekantong permen di tangan Anda, bukan? Makanlah beberapa potong saja, dan itu akan menahan Anda sampai makan malam.",
  ui_story_5034_50340201_12_dialog_content = "Tidak bisa, permen ini untuk Schewe dan Latan, serta anak-anak lain!",
  ui_story_5034_50340201_13_dialog_content = "Anda tidak tahu apa yang saya lalui untuk sekantong permen ini ...",
  ui_story_5034_50340201_14_dialog_content = "Omong-omong... di mana Schewe dan Latan?",
  ui_story_5034_50340201_15_dialog_content = "Apakah Anda tahu di mana mereka berdua, Corax?",
  ui_story_5034_50340201_16_dialog_content = "Maksudmu dua anak yang meminta permen, ya?",
  ui_story_5034_50340201_17_dialog_content = "Ya, mereka berdua!",
  ui_story_5034_50340201_18_dialog_content = "Mereka mengikuti Anda ke kota, jika saya ingat dengan benar.",
  ui_story_5034_50340201_19_dialog_content = "Tunggu apa? Mengapa mereka mengikuti saya?",
  ui_story_5034_50340201_20_dialog_content = "Setelah Anda meninggalkan gereja pagi ini, keduanya juga pergi tak lama kemudian.",
  ui_story_5034_50340201_21_dialog_content = "Saya pikir Anda semua bepergian sebagai sebuah kelompok ... Apakah itu berarti Anda tidak pernah melihat mereka saat Anda berada di kota?",
  ui_story_5034_50340201_22_dialog_content = "Aku tidak... Aku tidak tahu aku sedang diikuti. Tapi saya sudah kembali, jadi di mana mereka?",
  ui_story_5034_50340201_23_dialog_content = "Jangan panik, saya yakin mereka ada di mana pun Anda terakhir kali pergi.",
  ui_story_5034_50340201_24_dialog_content = "Kamu benar! Aku harus kembali dan mencari mereka!",
  ui_story_5034_50340201_25_dialog_content = "Aku akan segera kembali, Corax! Awasi anak-anak lain untukku, ya?",
  ui_story_5034_50340201_26_dialog_content = "Hai! Ambil ini juga!",
  ui_story_5034_50340201_27_dialog_content = "Apakah ini... <color=#FFB400>setengah roti</color>?",
  ui_story_5034_50340201_28_dialog_content = "Ini sedikit basi, tapi itu harus cukup.",
  ui_story_5034_50340201_29_dialog_content = "Jika saya membiarkan Caelestit terakhir di dunia mati kelaparan, saya harus menghabiskan sisa hidup saya di Euphoria.",
  ui_story_5034_50340201_30_dialog_content = "Terima kasih, Corax... Aku akan menikmati setiap gigitannya!",
  ui_story_5034_50340201_31_dialog_content = "(Schewe, Latan... Aku dalam perjalanan! Aku hanya berharap tidak ada hal buruk yang terjadi pada mereka...)",
  ui_story_5034_50340202_1_dialog_content = "Aku sama sekali tidak memperhatikan kehadiran mereka...",
  ui_story_5034_50340202_2_dialog_content = "Jangan bilang mereka ada di toko?",
  ui_story_5034_50340202_3_dialog_content = "Kacamata hitam untuk dijual!",
  ui_story_5034_50340202_4_dialog_content = "Gaya terbaru, langsung dari Umbraton!",
  ui_story_5034_50340202_5_dialog_content = "Hmm? Suara itu terdengar sangat familiar...",
  ui_story_5034_50340202_6_dialog_content = "Hei, tuan? Bisakah saya menarik minat Anda pada kacamata hitam?",
  ui_story_5034_50340202_7_dialog_content = "Mereka semua marah di Umbraton!",
  ui_story_5034_50340202_8_dialog_content = "Hah?",
  ui_story_5034_50340202_9_dialog_content = "Anda bilang saya terlihat seperti pria yang membutuhkan kacamata hitam?!",
  ui_story_5034_50340202_10_dialog_content = "Apa ada yang salah dengan cara pandang mataku?!",
  ui_story_5034_50340202_11_dialog_content = "T-Tidak sama sekali, Pak! aku tidak bermaksud seperti itu...",
  ui_story_5034_50340202_12_dialog_content = "Heh... Anda tahu, melihat pipsqueak seperti Anda bekerja mengingatkan saya pada diri saya sendiri ketika saya masih kecil.",
  ui_story_5034_50340202_13_dialog_content = "Baiklah nak, jangan bilang aku tidak pernah melakukan sesuatu yang baik untukmu. Berapa banyak untuk nuansa?",
  ui_story_5034_50340202_14_dialog_content = "Er... 6.000 Nightium sepasang...",
  ui_story_5034_50340202_15_dialog_content = "Hah? Anda punya nyali, gadis kecil... Mencoba untuk menipu orang agar membeli kacamata hitam dengan harga itu persis seperti yang saya lakukan sebagai seorang anak!",
  ui_story_5034_50340202_16_dialog_content = "Sayangnya, Anda memilih orang yang salah untuk diganggu hari ini. Biarkan aku memberimu rasa dunia nyata...",
  ui_story_5034_50340202_17_dialog_content = "*Hiks*",
  ui_story_5034_50340202_18_dialog_content = "Latan? Apa itu kamu?",
  ui_story_5034_50340202_19_dialog_content = "M-Mr. Navigator!",
  ui_story_5034_50340202_20_dialog_content = "*Menangis* Aku di sini...",
  ui_story_5034_50340202_21_dialog_content = "Nak, lebih baik kau mengurus urusanmu sendiri!",
  ui_story_5034_50340202_22_dialog_content = "Bagaimana jika saya tidak mau?",
  ui_story_5034_50340202_23_dialog_content = "Pembicaraan yang cukup sulit, untuk seseorang yang sendirian...",
  ui_story_5034_50340202_24_dialog_content = "Siapa bilang aku sendirian?",
  ui_story_5034_50340202_25_dialog_content = "Di sini, Corax! Pollux!",
  ui_story_5034_50340202_26_dialog_content = "Apa? Wanita gila itu juga ada di sini?!",
  ui_story_5034_50340202_27_dialog_content = "J-Tunggu saja, punk! Aku akan menjemputmu lain kali!",
  ui_story_5034_50340202_28_dialog_content = "PlayerName... Apakah Tuan Corax bersamamu juga?",
  ui_story_5034_50340202_29_dialog_content = "Bukankah dia seharusnya mengawasi anak-anak lain di gereja sekarang?",
  ui_story_5034_50340202_30_dialog_content = "Maaf, Latan... Aku baru saja menggertak untuk menakut-nakuti orang itu. Corax tidak ada di sini sama sekali.",
  ui_story_5034_50340202_31_dialog_content = "Jika Tuan Corax ada di sini, kita tidak perlu takut pada <color=#FFB400>penjaga toko</color> itu...",
  ui_story_5034_50340202_32_dialog_content = "(\"Penjaga Toko\"? Mungkinkah dia berbicara tentang penjaga toko ITU?)",
  ui_story_5034_50340202_33_dialog_content = "Lagi pula, apa yang terjadi di sini, Latan? Kenapa pria itu mengganggumu barusan?",
  ui_story_5034_50340202_34_dialog_content = "Dan di mana Schewe? Aku tidak melihatnya dimanapun...",
  ui_story_5034_50340202_35_dialog_content = "Saya akan memberitahu Anda apa yang saya lakukan nanti, Tn. Navigator. Adapun Schewe, dia ada di dalam toko.",
  ui_story_5034_50340202_36_dialog_content = "Yang dimana kamu membeli permen tadi hari...",
  ui_story_5034_50340202_37_dialog_content = "Saya mengerti. Saya tidak akan bertanya mengapa Anda mengikuti saya untuk saat ini.",
  ui_story_5034_50340202_38_dialog_content = "Ayo cari Schewe dulu, oke?",
  ui_story_5034_50340202_39_dialog_content = "Oke!",
  ui_story_5034_50340202_40_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5034_50340202_41_dialog_content = "Menjatuhkan barang daganganku ke lantai lagi, ya? Saya harus menambahkan itu ke hutang Anda juga.",
  ui_story_5034_50340202_42_dialog_content = "Sejujurnya... Anda datang ke sini untuk bekerja demi uang, tapi yang Anda lakukan hanyalah menimbun hutang.",
  ui_story_5034_50340202_43_dialog_content = "Jika Anda bahkan tidak dapat mengisi kembali rak saya dengan benar, saya sarankan Anda berhenti.",
  ui_story_5034_50340202_44_dialog_content = "Jika tidak, Anda akan berusia lima puluh tahun sebelum Anda melunasi hutang Anda! Ha ha ha ha!",
  ui_story_5034_50340202_45_dialog_content = "Aku... aku bisa melakukannya...",
  ui_story_5034_50340202_46_dialog_content = "<size=45>Ah!</size>",
  ui_story_5034_50340202_47_dialog_content = "<color=#e8d9bb>Dentang-Dentang!</color>",
  ui_story_5034_50340202_48_dialog_content = "Schewe!",
  ui_story_5034_50340202_49_dialog_content = "Kau baik-baik saja?!",
  ui_story_5034_50340202_50_dialog_content = "Saya baik-baik saja, Tuan Navigator... Tapi saya menjatuhkan kotak lain, jadi penjaga toko akan menambahkannya ke hutang saya lagi...",
  ui_story_5034_50340202_51_dialog_content = "Utang? Apa yang terjadi di sini?",
  ui_story_5034_50340202_52_dialog_content = "Yah, baiklah... Jika bukan Tuan \"Aku Tidak Akan Kembali Lagi,\" kembali lebih cepat dari yang diharapkan.",
  ui_story_5034_50340202_53_dialog_content = "Jika Anda harus tahu, anak ini berutang banyak uang kepada saya untuk semua masalah yang dia sebabkan kepada saya.",
  ui_story_5034_50340202_54_dialog_content = "...",
  ui_story_5034_50340202_55_dialog_content = "Jika itu masalahnya, maka mari kita selesaikan hal-hal dari \"transaksi\" kita sebelumnya, ya?",
  ui_story_5034_50340301_1_dialog_content = "Sangat baik. Karena Anda adalah pelanggan sebelumnya, saya sangat senang melakukannya. Apakah Anda ingin saya menjelaskan bagaimana hutang ini terjadi?",
  ui_story_5034_50340301_2_dialog_content = "Tidak, terima kasih, saya pikir saya akan mendengarnya dari keduanya.",
  ui_story_5034_50340301_3_dialog_content = "Schewe, Latan... Bisakah kalian memberitahuku apa yang sebenarnya terjadi di sini? Jangan khawatir, Anda tidak dalam masalah.",
  ui_story_5034_50340301_4_option_content = "Bisakah Anda memberi tahu saya mengapa Anda mengikuti saya?",
  ui_story_5034_50340301_5_dialog_content = "Maaf, Tn. Navigator... Kami hanya ingin melihat di mana Anda akan membeli permen itu.",
  ui_story_5034_50340301_6_dialog_content = "Kami mengikuti Anda sampai ke sini, dan kami melihat betapa kerasnya Anda bekerja untuk satu kantong permen itu.",
  ui_story_5034_50340301_7_option_content = "Bisakah Anda memberi tahu saya lebih banyak tentang \"hutang\" ini?",
  ui_story_5034_50340301_8_dialog_content = "Kami ingin melakukan hal yang sama seperti yang Anda lakukan, Tn. Navigator... Kami juga ingin bekerja keras untuk mendapatkan permen kami.",
  ui_story_5034_50340301_9_dialog_content = "Tapi ternyata pekerjaan itu jauh lebih sulit dari yang kita kira...",
  ui_story_5034_50340301_10_dialog_content = "Saya diberi tanggung jawab atas barang-barang toko. Pekerjaan saya adalah membawa barang-barang dari gudang ke toko, dan kemudian mengaturnya di rak.",
  ui_story_5034_50340301_11_dialog_content = "Tetapi penjaga toko mengatakan kepada saya bahwa saya tidak diizinkan untuk menyeret kotak-kotak itu ke tanah, atau barang dagangannya akan rusak.",
  ui_story_5034_50340301_12_dialog_content = "Saya tidak punya pilihan selain mencoba dan membawa setiap kotak, tetapi barang-barang di dalamnya sangat berat ...",
  ui_story_5034_50340301_13_dialog_content = "Jadi setiap kali aku menjatuhkan sebuah kotak, dia menambahkannya ke hutangku... Dia bilang itu untuk menebus kesalahanku dalam pekerjaan.",
  ui_story_5034_50340301_14_dialog_content = "Tapi saya memeriksa barang-barang di dalam kotak dan semuanya baik-baik saja!",
  ui_story_5034_50340301_15_option_content = "Apa yang kamu lakukan di luar tadi, Latan?",
  ui_story_5034_50340301_16_dialog_content = "Penjaga toko mengatakan bahwa karena saya sangat imut, saya harus pergi ke luar dan menjual kacamata hitam kepada orang-orang saat mereka melewati toko.",
  ui_story_5034_50340301_17_dialog_content = "Tapi tidak ada yang pernah berhenti untuk mendengarkan saya ...",
  ui_story_5034_50340301_18_dialog_content = "Kecuali pria yang tampak marah itu. Dia satu-satunya yang berhenti untuk mendengarkan...",
  ui_story_5034_50340301_19_dialog_content = "Tapi dia semakin marah dan semakin marah... dan aku sangat takut...",
  ui_story_5034_50340301_19X1_dialog_content = "Itu saja. Maaf, PlayerName.",
  ui_story_5034_50340301_20_dialog_content = "Saya pikir saya mengerti sekarang. Satu pertanyaan terakhir...",
  ui_story_5034_50340301_21_option_content = "Mengapa kalian ingin bekerja untuk permen?",
  ui_story_5034_50340301_22_dialog_content = "Jika Anda mengikuti saya selama ini, maka Anda pasti tahu bahwa saya sudah membeli permen itu.",
  ui_story_5034_50340301_23_dialog_content = "Mengapa Anda ingin bekerja lebih banyak lagi?",
  ui_story_5034_50340301_24_dialog_content = "Yah... Setelah kami melihat betapa kerasnya kau bekerja hanya untuk membelikan kami permen...",
  ui_story_5034_50340301_25_dialog_content = "Kami tidak ingin terlihat seperti sepasang anak yang egois dan nakal.",
  ui_story_5034_50340301_26_dialog_content = "Jadi kami memutuskan untuk bekerja keras agar kami bisa membagi penghasilan kami dengan Anda dan Pollux, karena dia selalu menjaga kami.",
  ui_story_5034_50340301_27_dialog_content = "Pollux pernah menceritakan kisah bagaimana seorang biarawati merawatnya di masa lalu.",
  ui_story_5034_50340301_28_dialog_content = "Dia berkata bahwa salah satu alasan dia mengambil alih tanggung jawab gereja dan mengambil anak yatim seperti kami... adalah untuk menunjukkan rasa terima kasihnya atas kebaikan biarawati itu.",
  ui_story_5034_50340301_29_dialog_content = "Aku ingat ekspresi wajahnya ketika dia mengatakan kepada kami bahwa... Itu sangat baik dan hangat.",
  ui_story_5034_50340301_30_dialog_content = "Saat itulah saya memutuskan bahwa saya perlu menjadi <color=#FFB400>seseorang yang memahami rasa terima kasih</color> juga.",
  ui_story_5034_50340301_31_dialog_content = "Seseorang yang bersyukur dan hangat, sama seperti dia.",
  ui_story_5034_50340301_32_dialog_content = "Aku juga ingin seperti itu... Untuk membuat orang lain merasa hangat, seperti Pollux dan kamu.",
  ui_story_5034_50340301_33_dialog_content = "Tapi sepertinya yang kita lakukan hanyalah mengacaukan semuanya...",
  ui_story_5034_50340301_34_dialog_content = "Aku tahu.",
  ui_story_5034_50340301_35_dialog_content = "Memainkan trik kotor seperti itu pada anak-anak tak berdosa seperti ini...",
  ui_story_5034_50340301_36_dialog_content = "Apakah ini bagaimana hal-hal terbang di Euforia?",
  ui_story_5034_50340301_37_dialog_content = "Saya hanya mencoba mengajari mereka untuk bertanggung jawab atas konsekuensi dari pilihan mereka.",
  ui_story_5034_50340301_38_dialog_content = "Jika dipikir-pikir, hutang mereka padaku seperti uang sekolah untuk pelajaranku.",
  ui_story_5034_50340301_39_dialog_content = "*Menangis* PlayerName... Aku takut ... Aku ingin kembali ke gereja ...",
  ui_story_5034_50340301_40_dialog_content = "(Lupakan saja. Tidak ada gunanya mencoba berunding dengan penjaga toko yang tidak tahu malu ini.)",
  ui_story_5034_50340301_41_dialog_content = "(Aku harus mencari cara untuk mengeluarkan anak-anak ini dari sini dulu. Bahkan jika aku ingin membalas orang itu, aku harus mendiskusikannya dengan Corax dulu.)",
  ui_story_5034_50340301_42_dialog_content = "(Saya sendirian sekarang, jadi sebaiknya saya tidak memulai apa pun.)",
  ui_story_5034_50340301_43_dialog_content = "Anak-anak ini hanya ingin membeli dua bungkus permen. Aku akan membayarnya.",
  ui_story_5034_50340301_44_dialog_content = "Beri saja mereka permen dan biarkan mereka pergi. Saya akan melunasi sisa hutang mereka di tempat mereka.",
  ui_story_5034_50340301_45_dialog_content = "Apakah Anda sudah lupa apa yang terjadi pagi ini, teman saya?",
  ui_story_5034_50340301_46_dialog_content = "Apakah Anda yakin Anda mampu membeli permen ini?",
  ui_story_5034_50340301_47_dialog_content = "Heh, Anda punya keberanian, mengungkitnya. Tentu saja saya tidak lupa.",
  ui_story_5034_50340301_48_dialog_content = "Terlebih lagi, saya menemukan ini tercetak di tas!",
  ui_story_5034_50340301_49_dialog_content = "Anda tidak hanya menjual barang palsu, Anda juga menagih seratus kali lipat dari harga eceran yang disarankan! Saya masih belum menyelesaikan skor dengan Anda tentang itu!",
  ui_story_5034_50340301_50_dialog_content = "Ha ha ha! Jadi bagaimana jika Anda mengetahuinya? Saya tidak ingat mengatakan bahwa barang dagangan saya asli, bukan?",
  ui_story_5034_50340301_51_dialog_content = "Selain itu, ini adalah toko saya, dan saya diizinkan untuk menetapkan harga sesuai keinginan saya.",
  ui_story_5034_50340301_52_dialog_content = "Adapun transaksi kami, Anda bersedia untuk membeli, dan saya bersedia untuk menjual... Begitulah cara bisnis bekerja, Anda setuju?",
  ui_story_5034_50340301_53_dialog_content = "Mari kita lupakan permen itu, PlayerName...",
  ui_story_5034_50340301_54_dialog_content = "Oh, tidak ada yang akan menarik kembali kata-kata Anda sekarang. Anda meminta dua tas, dan sekarang Anda harus membayarnya.",
  ui_story_5034_50340301_55_dialog_content = "Berhenti menakut-nakuti anak-anak sudah! Aku bilang aku akan membayar untuk mereka.",
  ui_story_5034_50340301_56_dialog_content = "Kami akan melakukannya seperti pagi ini. Saya akan bekerja untuk kedua kantong permen.",
  ui_story_5034_50340301_57_dialog_content = "Baiklah, tetapi Anda harus bekerja dua kali lebih banyak dari pagi ini.",
  ui_story_5034_50340301_58_dialog_content = "Adapun anak-anak, mereka harus tinggal di sini sampai Anda menyelesaikan pekerjaan Anda.",
  ui_story_5034_50340301_59_dialog_content = "Saya tidak akan mengambil risiko Anda banyak melarikan diri ketika kepala saya menoleh.",
  ui_story_5034_50340301_60_dialog_content = "Biarkan kami membantu Anda, Tn. Navigator.",
  ui_story_5034_50340301_61_dialog_content = "Aku akan baik-baik saja, Schewe. Kalian berdua bisa duduk di sana dan menonton. Saya sudah melakukan ini sekali, jadi tidak perlu khawatir.",
  ui_story_5034_50340301_62_dialog_content = "Oh, dan ini sekantong permen yang saya janjikan sebelumnya. Kamu bisa ngemil sambil menungguku, oke?",
  ui_story_5034_50340301_63_dialog_content = "Percayalah, saya akan selesai sebelum Anda menyadarinya, dan kami akan kembali ke gereja dalam waktu singkat!",
  ui_story_5034_50340302_1_dialog_content = "(Berkat pengalaman saya dari pagi, saya benar-benar akrab dengan pekerjaan itu.)",
  ui_story_5034_50340302_2_dialog_content = "(Akibatnya, saya dapat melakukan pekerjaan dua kali lipat hanya dalam separuh waktu!)",
  ui_story_5034_50340302_3_dialog_content = "(Kurasa itu semua dalam pekerjaan sehari bagi saya sebagai Pelari Tugas Nomor Satu Astra ... Heheh ...)",
  ui_story_5034_50340302_4_dialog_content = "Selesai begitu cepat? Saya kira saya salah untuk meremehkan Anda, setelah semua.",
  ui_story_5034_50340302_5_dialog_content = "Cukup obrolan ringan. Beri saja anak-anak permen mereka dan biarkan mereka pergi.",
  ui_story_5034_50340302_6_dialog_content = "Tidak perlu bersikap kasar. Tunggu di sini, dan aku akan mengambilnya.",
  ui_story_5034_50340302_7_dialog_content = "Oh sayang, belasungkawa saya, teman.",
  ui_story_5034_50340302_8_dialog_content = "Saya baru saja memeriksa rak saya, dan sepertinya semua permen terjual habis.",
  ui_story_5034_50340302_9_dialog_content = "Apa? Mengapa Anda tidak memberi tahu kami lebih awal? Apa gunanya semua pekerjaan yang saya lakukan barusan?!",
  ui_story_5034_50340302_10_dialog_content = "Sekali lagi, tidak perlu kasar. Anda bekerja untuk saya dua kali dalam satu hari. Kedengarannya seperti sudah ditakdirkan oleh takdir, jika aku sendiri yang mengatakannya.",
  ui_story_5034_50340302_11_dialog_content = "Ditambah lagi, saya tidak akan pernah bermimpi mengeksploitasi pekerja saya seperti majikan kejam lainnya.",
  ui_story_5034_50340302_12_dialog_content = "Bagaimana kalau saya membayar Anda di Nightium untuk dua kantong permen itu? Apakah itu adil?",
  ui_story_5034_50340302_13_dialog_content = "(Yah, aku sudah bisa mendapatkan permen untuk anak-anak...)",
  ui_story_5034_50340302_14_dialog_content = "(Jika saya menyetujui saran penjaga toko, itu berarti dia berutang 6.000 Nightium kepada saya.)",
  ui_story_5034_50340302_15_dialog_content = "(Itu seharusnya lebih dari cukup bagi mereka untuk membeli Pollux sesuatu yang lain sebagai hadiah.)",
  ui_story_5034_50340302_16_dialog_content = "Baiklah, aku akan menerima tawaranmu.",
  ui_story_5034_50340302_17_dialog_content = "Terima kasih atas pengertian Anda! Beri saya waktu sebentar, dan saya akan kembali dengan gaji Anda.",
  ui_story_5034_50340302_18_dialog_content = "Baiklah, ini dia. Terima kasih sekali lagi atas kerja keras Anda!",
  ui_story_5034_50340302_19_dialog_content = "10, 20, 30... Tunggu, ini hanya 60 Nightium!",
  ui_story_5034_50340302_20_dialog_content = "Apa yang kamu mainkan di sini? Bukankah seharusnya 6.000 Nightium?",
  ui_story_5034_50340302_21_dialog_content = "Tidak salah lagi, kawan. Setiap tas bernilai 30 Nightium, jadi dua tas akan menjadi 60 Nightium secara total.",
  ui_story_5034_50340302_22_dialog_content = "Bahkan kedua anak itu bisa dengan mudah mengerjakan soal matematika.",
  ui_story_5034_50340302_23_dialog_content = "Tapi setiap tas bernilai 3.000 Nightium, bukan 30!",
  ui_story_5034_50340302_24_dialog_content = "Ah... Kau begitu mudah melupakan hal-hal, temanku.",
  ui_story_5034_50340302_25_dialog_content = "Anda adalah orang yang memberi tahu saya bahwa setiap tas hanya bernilai 30 Nightium, Anda tahu.",
  ui_story_5034_50340302_26_dialog_content = "Melihat? Jika Anda lupa, itu tercetak di sini di tas.",
  ui_story_5034_50340302_27_dialog_content = "Bagaimana Anda bisa menjadi tak tahu malu ini?!",
  ui_story_5034_50340302_28_dialog_content = "Hmph ... Saya akan berpikir bahwa setelah menghabiskan hampir sepanjang hari di sini, Anda setidaknya memiliki firasat tentang aturan Euphoria.",
  ui_story_5034_50340302_29_dialog_content = "Aturan, aturan, aturan... Saya tidak ingin mendengar tentang \"aturan Euphoria\" lagi!",
  ui_story_5034_50340302_30_dialog_content = "Anda selalu yang diuntungkan, jadi aturan siapa ini?!",
  ui_story_5034_50340302_31_dialog_content = "Ha ha ha! Apakah Anda akhirnya mulai mengerti, teman muda saya?",
  ui_story_5034_50340302_32_dialog_content = "Tentu saja saya selalu di pihak yang menang... Karena mereka yang tidak punya uang atau pengaruh tidak mendikte aturan di sini.",
  ui_story_5034_50340302_33_dialog_content = "Aku sudah selesai membicarakan ini denganmu... Schewe, Latan, ayo pergi dari sini.",
  ui_story_5034_50340302_34_dialog_content = "Schewe?",
  ui_story_5034_50340302_35_dialog_content = "Latan?",
  ui_story_5034_50340302_36_dialog_content = "Kamu mau pergi kemana?!",
  ui_story_5034_50340302_37_dialog_content = "Dan di mana Anda pikir Anda akan pergi? Masih ada masalah utang mereka, lho?",
  ui_story_5034_50340302_38_dialog_content = "Di mana Anda menyembunyikan anak-anak? Anda sebaiknya tidak melakukan apa pun pada mereka!",
  ui_story_5034_50340302_39_dialog_content = "Apa yang saya putuskan untuk dilakukan dengan mereka sepenuhnya tergantung pada Anda, teman saya.",
  ui_story_5034_50340302_40_dialog_content = "Kamu...",
  ui_story_5034_50340401_1_dialog_content = "Apa sebenarnya yang harus saya lakukan agar Anda melepaskan keduanya?",
  ui_story_5034_50340401_2_dialog_content = "Saya hanyalah seorang pedagang sederhana dengan tuntutan sederhana. Yang saya minta adalah Anda melunasi hutang mereka.",
  ui_story_5034_50340401_3_dialog_content = "Tapi Anda benar-benar membuat hutang itu!",
  ui_story_5034_50340401_4_dialog_content = "Nah, jika Anda tidak mau melunasinya, Anda bisa melupakan pergi dari sini bersama kedua anak itu.",
  ui_story_5034_50340401_5_dialog_content = "Kamu keparat...!",
  ui_story_5034_50340401_6_dialog_content = "(Tunggu... Apakah dia baru saja mendekatiku, atau apakah aku merasakan Eclipsites di dekatnya?)",
  ui_story_5034_50340401_7_dialog_content = "(Di sana! Tirai di belakang penjaga toko! Di sanalah mereka bersembunyi!)",
  ui_story_5034_50340401_8_dialog_content = "(Dia seharusnya tidak begitu tenang jika ada Eclipsites muncul di tokonya.)",
  ui_story_5034_50340401_9_dialog_content = "(Kecuali...)",
  ui_story_5034_50340401_10_dialog_content = "Apakah Anda... menyembunyikan Eclipsites di toko Anda?",
  ui_story_5034_50340401_11_dialog_content = "Tidak ada gunanya berbohong. Aku sudah merasakan kehadiran mereka.",
  ui_story_5034_50340401_12_dialog_content = "Oh? Jadi kau Caelestit yang dibicarakan semua orang.",
  ui_story_5034_50340401_13_dialog_content = "Nah, karena Anda sudah menemukan sebanyak itu, saya kira tidak ada salahnya menunjukkannya kepada Anda.",
  ui_story_5034_50340401_14_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5034_50340401_15_dialog_content = "K-Kamu... Bagaimana kamu bisa membuat anak-anak terkurung dengan Eclipsites?!",
  ui_story_5034_50340401_16_dialog_content = "Waaaah!!",
  ui_story_5034_50340401_17_dialog_content = "Tuan Navigator! S-Selamatkan aku...!",
  ui_story_5034_50340401_18_dialog_content = "D-Dia bilang kalau kita membuat keributan, dia akan menyuruh Eclipsites untuk memakan kita...!",
  ui_story_5034_50340401_19_dialog_content = "Cukup, Latan. Jangan menangis lagi...",
  ui_story_5034_50340401_20_dialog_content = "Kami sudah membuat cukup banyak masalah untuk Tn. Navigator...",
  ui_story_5034_50340401_21_dialog_content = "Semua ini bukan salah kalian! Ini salahku karena membuat semua janji itu pagi ini.",
  ui_story_5034_50340401_22_dialog_content = "Jangan khawatir! Aku akan pastikan untuk membawamu pulang, aman dan sehat.",
  ui_story_5034_50340401_23_dialog_content = "Ah... Membuat lebih banyak janji, begitu?",
  ui_story_5034_50340401_24_dialog_content = "Kau bajingan... Kau rela membuang kemanusiaanmu, semua demi sedikit uang?!",
  ui_story_5034_50340401_25_dialog_content = "Ha ha ha ha! Anda tidak berpikir itu lucu untuk berbicara tentang hal-hal seperti \"kemanusiaan\" dan \"kesopanan\" di Euforia dari semua tempat?",
  ui_story_5034_50340401_26_dialog_content = "Selain itu, saya sudah memberi tahu Anda apa yang perlu dilakukan untuk menyelamatkan mereka. Aku tidak sepenuhnya tidak berperasaan, kau tahu?",
  ui_story_5034_50340401_27_dialog_content = "Anda dapat menyimpannya... atau tidak. Pilihanmu.",
  ui_story_5034_50340401_28_dialog_content = "(Tentu saja saya harus menyelamatkan mereka, tetapi saya tidak bisa terus membiarkan orang ini berada di atas angin!)",
  ui_story_5034_50340401_29_dialog_content = "(Tali mengikat tangan mereka bersama-sama melekat pada leher Eclipsites.)",
  ui_story_5034_50340401_30_dialog_content = "(Jika saya ingin menyelamatkan mereka, saya juga harus melepaskan tali di sekitar Eclipsites.)",
  ui_story_5034_50340401_31_dialog_content = "(Sepertinya aku harus mengambil kesempatan. Pinjami aku sedikit keberuntunganmu, Casta...)",
  ui_story_5034_50340401_32_dialog_content = "Aku telah mengambil keputusan.",
  ui_story_5034_50340401_33_dialog_content = "Begitu cepat? Sangat bagus, sekarang mari kita lihat apakah itu yang benar.",
  ui_story_5034_50340401_34_dialog_content = "aku sudah memutuskan...",
  ui_story_5034_50340401_35_dialog_content = "Untuk melakukan ini!",
  ui_story_5034_50340401_36_dialog_content = "Argh! Kamu... Apakah kamu baru saja melempar batu ke arahku?! Mataku...!",
  ui_story_5034_50340401_37_dialog_content = "Anda telah datang!",
  ui_story_5034_50340401_38_dialog_content = "(Untung saya tidak memakannya. Corax tidak bercanda ketika dia mengatakan itu agak basi.)",
  ui_story_5034_50340401_39_dialog_content = "(Sudahlah, tidak ada waktu untuk disia-siakan! Saya harus menyelamatkan anak-anak!)",
  ui_story_5034_50340401_40_dialog_content = "Tuan Navigator!",
  ui_story_5034_50340401_41_dialog_content = "Saya tahu Anda akan menyelamatkan kami!",
  ui_story_5034_50340401_42_dialog_content = "Dengar, kalian berdua! Segera setelah saya melepaskan tali ini, Anda harus lari secepat mungkin!",
  ui_story_5034_50340401_43_dialog_content = "Dan jangan kembali untuk alasan apa pun, mengerti?",
  ui_story_5034_50340401_44_dialog_content = "Tapi bagaimana denganmu?",
  ui_story_5034_50340401_45_dialog_content = "Dia menggunakan tali yang sama untuk mengikatmu dan Eclipsites. Untuk melepaskanmu, aku juga harus membebaskan Eclipsites.",
  ui_story_5034_50340401_46_dialog_content = "Begitu saya melakukannya, saya akan mendapatkan perhatian mereka dan berlari ke arah yang berlawanan. Jangan khawatir tentang saya, saya akan baik-baik saja!",
  ui_story_5034_50340401_47_dialog_content = "Navigator...",
  ui_story_5034_50340401_48_dialog_content = "Baiklah, kita tidak punya waktu untuk kalah. Pada hitungan ketiga, kalian kehabisan secepat mungkin, mengerti?",
  ui_story_5034_50340401_49_dialog_content = "Satu...",
  ui_story_5034_50340401_50_dialog_content = "Dua...",
  ui_story_5034_50340401_51_dialog_content = "Tiga!",
  ui_story_5034_50340401_52_dialog_content = "<size=45>Lari!</size>",
  ui_story_5034_50340402_1_dialog_content = "Grr... Graa...",
  ui_story_5034_50340402_2_dialog_content = "Graah...",
  ui_story_5034_50340402_3_dialog_content = "Urgh... Aku tidak bisa terus membiarkan mereka mengejarku seperti ini. pada akhirnya aku akan lelah sendiri...",
  ui_story_5034_50340402_4_dialog_content = "Saya perlu memikirkan rencana untuk melepaskan mereka, dan cepat!",
  ui_story_5034_50340402_5_dialog_content = "Tunggu... Jika aku ingat dengan benar, jalan di depan itu adalah jalan yang aku dan Corax ambil untuk memasuki kota!",
  ui_story_5034_50340402_6_dialog_content = "Saya pikir saya punya ide!",
  ui_story_5034_50340402_7_dialog_content = "Hei, kamu bodoh! Kamu bilang <color=#FFB400>takdir</color> terus menyatukan kita, kan? Nah, kembali pada Anda!",
  ui_story_5034_50340402_8_dialog_content = "Astaga!!",
  ui_story_5034_50340402_9_dialog_content = "Graaaah!!",
  ui_story_5034_50340402_10_dialog_content = "Dasar brengsek, apa kau bersembunyi di belakangku dengan Eclipsites di ekormu?",
  ui_story_5034_50340402_11_dialog_content = "Pantainya jernih. Anda bisa keluar sekarang.",
  ui_story_5034_50340402_12_dialog_content = "Wow, kamu benar-benar mengeluarkan semuanya... Kamu tidak setengah jahat, pria besar!",
  ui_story_5034_50340402_13_dialog_content = "Kita bertemu lagi. Tidak bisa menghadapiku seperti pria sejati, jadi kamu menggunakan trik kotor semacam ini?",
  ui_story_5034_50340402_14_dialog_content = "T-Tidak, bukan itu sama sekali! Bagaimanapun, aku harus pergi ke suatu tempat sekarang, jadi... Sampai jumpa!",
  ui_story_5034_50340402_15_dialog_content = "Tidak bisa cukup berterima kasih atas bantuan Anda, pria besar! <color=#FFB400>Sampai takdir mempertemukan kita lagi</color>!!",
  ui_story_5034_50340402_16_dialog_content = "Hai! Oi—!",
  ui_story_5034_50340402_17_dialog_content = "Panggil aku PlayerName! Temukan saya jika Anda pernah di Eraveil, dan saya akan mengajak Anda berkeliling!",
  ui_story_5034_50340402_18_dialog_content = "(Syukurlah aku ingat jalan itu penuh dengan preman. Aku bisa menggunakannya untuk menyingkirkan Eclipsites itu!)",
  ui_story_5034_50340402_19_dialog_content = "(Saya sangat senang semuanya berjalan sesuai rencana, atau saya akan berada dalam masalah besar.)",
  ui_story_5034_50340402_20_dialog_content = "Aneh... Sepertinya tidak ada orang di dalam toko.",
  ui_story_5034_50340402_21_dialog_content = "Penjaga toko dan sisa Eclipsites-nya tidak terlihat di mana pun ...",
  ui_story_5034_50340402_22_dialog_content = "Oh tidak... Mungkinkah mereka mengejar Schewe dan Latan?!",
  ui_story_5034_50340402_23_dialog_content = "Ini buruk... Aku harus mengejar mereka dan—",
  ui_story_5034_50340402_23X1_dialog_content = "<size=45>Aduh!</size>",
  ui_story_5034_50340402_24_dialog_content = "Astaga, itu menyakitkan...",
  ui_story_5034_50340402_25_dialog_content = "Kenapa kau terlihat sangat kusut? Apa yang terjadi?",
  ui_story_5034_50340402_26_dialog_content = "Dan mengapa tidak ada orang di sini?",
  ui_story_5034_50340402_27_dialog_content = "Casta...? Apakah itu benar-benar kamu?",
  ui_story_5034_50340402_28_dialog_content = "Ya, ini aku. Apa yang terjadi disini? Dan apa yang terjadi denganmu?",
  ui_story_5034_50340402_29_dialog_content = "Casta! Aku sangat senang kau di sini...",
  ui_story_5034_50340402_30_dialog_content = "Kami agak dalam masalah sekarang. Saya akan mencoba untuk membuatnya singkat ...",
  ui_story_5034_50340402_31_dialog_content = "<color=#e8d9bb>Setelah menjelaskan semuanya kepada Casta...</color>",
  ui_story_5034_50340402_32_dialog_content = "Saya pikir itu aneh bahwa pintu toko terbuka lebar, itulah sebabnya saya berhenti untuk melihatnya. Saya tidak tahu semua drama itu turun.",
  ui_story_5034_50340402_33_dialog_content = "Maaf, Casta... Aku tidak bisa melindungi Schewe dan Latan...",
  ui_story_5034_50340402_34_dialog_content = "Sekarang bukan saatnya menyalahkan diri sendiri, apalagi dengan kondisi Anda.",
  ui_story_5034_50340402_35_dialog_content = "Lagi pula, Anda tidak sendiri lagi. Saya di sini sekarang.",
  ui_story_5034_50340402_36_dialog_content = "Apapun yang terjadi, kita bisa mencari solusi bersama.",
  ui_story_5034_50340402_37_dialog_content = "Kami juga tahu ke arah mana mereka berlari, jadi jangan terlalu khawatir.",
  ui_story_5034_50340402_38_dialog_content = "Bagaimanapun, ini adalah Euforia. Aku tidak akan membiarkan apa pun terjadi pada mereka berdua.",
  ui_story_5034_50340402_39_dialog_content = "Terima kasih, Casta... Aku tidak tahu kau bisa begitu menghibur.",
  ui_story_5034_50340402_40_dialog_content = "... Saya tidak tahu apa yang Anda bicarakan.",
  ui_story_5034_50340402_41_dialog_content = "Baiklah, mari kita pergi! Kita harus menemukan keduanya, apa pun yang terjadi.",
  ui_story_5034_50340402_42_dialog_content = "Memimpin.",
  ui_story_5034_50340501_1_dialog_content = "Aku bisa merasakan Eclipsites di dekatnya... Jalan ini seharusnya.",
  ui_story_5034_50340501_2_dialog_content = "Aku benar-benar berharap tidak ada hal buruk yang terjadi pada mereka, atau aku—",
  ui_story_5034_50340501_3_dialog_content = "Kau bilang mereka datang mencari pekerjaan, jadi mereka bisa membayarmu dan Pollux, kan?",
  ui_story_5034_50340501_4_dialog_content = "Apakah itu sebabnya Anda merasa sangat bertanggung jawab atas keselamatan mereka?",
  ui_story_5034_50340501_5_dialog_content = "Ya, tapi itu bukan satu-satunya alasan... Jika saya tidak membuat banyak janji idealis, semua ini tidak akan terjadi.",
  ui_story_5034_50340501_6_dialog_content = "Mulut besarkulah yang membuat mereka terlibat dalam kekacauan ini. Dan semua karena mereka ingin bekerja keras untuk membelikanku permen...",
  ui_story_5034_50340501_7_dialog_content = "Begitulah mereka berdua, jujur saja.",
  ui_story_5034_50340501_8_dialog_content = "Selama beberapa tahun terakhir, Pollux dan saya telah mengambil setidaknya tujuh puluh atau delapan puluh anak yatim di sini di Euphoria.",
  ui_story_5034_50340501_9_dialog_content = "Dan meskipun kebanyakan dari mereka memiliki kepribadian yang sangat berbeda, kedua anak itu menonjol dengan cara yang sangat tak terlupakan.",
  ui_story_5034_50340501_10_option_content = "Apa yang Anda maksud dengan \"tak terlupakan\"?",
  ui_story_5034_50340501_11_dialog_content = "Ikatan di antara mereka luar biasa.",
  ui_story_5034_50340501_12_dialog_content = "Latan mengubah Schewe menjadi lebih baik, dan Schewe melindungi Latan dengan segala cara. Hanya mereka yang dapat melakukan hal-hal ini untuk satu sama lain.",
  ui_story_5034_50340501_13_option_content = "Aku juga merasa seperti itu.",
  ui_story_5034_50340501_14_dialog_content = "Aku tahu kamu akan mengerti.",
  ui_story_5034_50340501_15_dialog_content = "Bagaimanapun, mereka cukup istimewa.",
  ui_story_5034_50340501_16_dialog_content = "Jika saya ingat dengan benar, Pollux menyelamatkan Schewe dari sarang perjudian bawah tanah.",
  ui_story_5034_50340501_17_dialog_content = "Ketika dia pertama kali datang ke gereja, dia menolak untuk mengangkat kepalanya atau menatap mata siapa pun.",
  ui_story_5034_50340501_18_dialog_content = "Dan dia selalu berbicara kepada orang lain dengan cara yang sangat sopan dan menyanjung, bahkan kepada anak-anak yang lebih muda darinya.",
  ui_story_5034_50340501_19_dialog_content = "Karena di sarang perjudian itu, sanjungan adalah satu-satunya cara untuk mendapatkan makanan dan menghindari hukuman.",
  ui_story_5034_50340501_20_dialog_content = "Dia telah menghabiskan sebagian besar hidupnya hidup dalam ketakutan.",
  ui_story_5034_50340501_21_dialog_content = "Pollux dan aku mencoba segalanya, tapi kami tidak bisa menembus tembok yang dia bangun di sekelilingnya.",
  ui_story_5034_50340501_22_dialog_content = "Kemudian suatu hari, Latan tiba di gereja, dan semuanya berubah.",
  ui_story_5034_50340501_23_dialog_content = "<color=#e8d9bb>Satu Tahun Yang Lalu</color>",
  ui_story_5034_50340501_24_dialog_content = "*Hiks*",
  ui_story_5034_50340501_25_dialog_content = "K-Kenapa kamu menangis? Apakah karena saya melakukan pekerjaan yang buruk membungkus perban Anda?",
  ui_story_5034_50340501_26_dialog_content = "maafkan aku... aku tidak baik dengan hal seperti ini...",
  ui_story_5034_50340501_27_dialog_content = "Aku sudah berlatih begitu banyak, tapi aku masih tidak bisa melakukannya sebaik Casta...",
  ui_story_5034_50340501_28_dialog_content = "Ini semua salahku... Tolong jangan menangis...",
  ui_story_5034_50340501_29_dialog_content = "*Menangis* Aku... Aku tidak menangis karena itu...",
  ui_story_5034_50340501_30_dialog_content = "Itu karena pria dengan bekas luka di wajahnya...",
  ui_story_5034_50340501_31_dialog_content = "Dia bilang dia harus memotong rambutku agar dia bisa menjahit luka di kepalaku hingga tertutup...",
  ui_story_5034_50340501_32_dialog_content = "Seorang pria dengan bekas luka di wajahnya? Maksudmu Nekoyashiki?",
  ui_story_5034_50340501_33_dialog_content = "Lalu apa yang terjadi? Apa yang dia lakukan padamu?",
  ui_story_5034_50340501_34_dialog_content = "Lalu... Lalu... Dia memotong poniku dan membuatku terlihat seperti ini!",
  ui_story_5034_50340501_35_dialog_content = "*Menangis* Aku terlihat mengerikan sekarang... Waaaaaah!",
  ui_story_5034_50340501_36_dialog_content = "Hah? Apakah itu semuanya? Kau terlihat baik! Sebenarnya, jika saya melihat lebih dekat... *kekek*",
  ui_story_5034_50340501_37_dialog_content = "Melihat! Anda juga tertawa! Aku tahu itu, aku terlihat seperti orang aneh! Waaaah!",
  ui_story_5034_50340501_38_dialog_content = "Tidak, bukan itu! Jika ada, Anda terlihat lebih manis sekarang. Betulkah!",
  ui_story_5034_50340501_39_dialog_content = "K-Kamu berbohong... Kamu hanya mengatakan itu untuk membuatku merasa lebih baik, bukan?",
  ui_story_5034_50340501_40_dialog_content = "Apa?! Tapi aku tidak berbohong padamu! Itulah yang saya rasakan, saya janji!",
  ui_story_5034_50340501_41_dialog_content = "*mengendus* Maaf, tapi bisakah aku menyentuh rambutmu sebentar? Jika saya melakukan ini, dan kemudian ini ...",
  ui_story_5034_50340501_42_dialog_content = "Tunggu di sini, aku akan mengambil cermin!",
  ui_story_5034_50340501_43_dialog_content = "Sehat? Bagaimana menurutmu?",
  ui_story_5034_50340501_44_dialog_content = "*Mengendus*",
  ui_story_5034_50340501_44X1_dialog_content = "Yah ... saya pikir itu terlihat sedikit berbeda ...",
  ui_story_5034_50340501_45_dialog_content = "Malah jadi manis sekarang...",
  ui_story_5034_50340501_45X1_dialog_content = "(T-Sebenarnya tidak ada bedanya... Aku sebenarnya tidak apa-apa...)",
  ui_story_5034_50340501_46_dialog_content = "Ah! A-Apakah aneh bagiku untuk mengatakan itu? Akankah yang lain berpikir aku benar-benar sombong sekarang?",
  ui_story_5034_50340501_47_dialog_content = "Meskipun, aku benar-benar terlihat imut, heehee...",
  ui_story_5034_50340501_48_dialog_content = "Melihat? Aku bilang aku tidak berbohong.",
  ui_story_5034_50340501_49_dialog_content = "Nama saya Latan. Apa milikmu?",
  ui_story_5034_50340501_50_dialog_content = "Aku... Schewe.",
  ui_story_5034_50340501_51_dialog_content = "Skema-kita!",
  ui_story_5034_50340501_52_dialog_content = "Ya! Nama sahabat baruku adalah Sche-we!",
  ui_story_5034_50340501_53_dialog_content = "B-Terbaik... teman?",
  ui_story_5034_50340501_54_dialog_content = "Maksudmu kamu tidak ingin berteman?",
  ui_story_5034_50340501_55_dialog_content = "T-Tidak, tentu saja aku ingin berteman!",
  ui_story_5034_50340501_56_dialog_content = "Aku akan menjadi sahabatmu, dan kamu juga bisa menjadi sahabatku! Oke?",
  ui_story_5034_50340501_57_dialog_content = "Oke!",
  ui_story_5034_50340501_58_dialog_content = "Saya pikir keduanya hanya suka bermain bersama. Saya tidak tahu mereka memiliki masa lalu seperti itu.",
  ui_story_5034_50340501_59_dialog_content = "Hanya seseorang yang polos dan tulus seperti Latan yang bisa meruntuhkan tembok yang mengelilingi hati Schewe... Ini benar-benar persahabatan yang langka.",
  ui_story_5034_50340501_60_dialog_content = "Kau benar, jadi Schewe tidak akan membiarkan apapun terjadi pada Latan. Dia anak yang cerdas. Jangan terlalu khawatir.",
  ui_story_5034_50340501_61_dialog_content = "Yeah... Tapi tetap saja, aku merasa sedikit khawatir. Juga...",
  ui_story_5034_50340501_62_dialog_content = "Juga?",
  ui_story_5034_50340501_63_dialog_content = "Perhatikan punggungmu! Ada Eclipsite di belakang kita!",
  ui_story_5034_50340501_64_dialog_content = "Grr... Graa...",
  ui_story_5034_50340501_65_dialog_content = "Heh, lihat ini.",
  ui_story_5034_50340501_66_dialog_content = "Graaah—",
  ui_story_5034_50340501_67_dialog_content = "Tunggu, aku cukup yakin Eclipsite ini terlihat seperti yang ada di dalam toko.",
  ui_story_5034_50340501_68_dialog_content = "Itu berarti kita berada di jalur yang benar. Keduanya pasti pernah lewat sini di beberapa titik.",
  ui_story_5034_50340501_69_dialog_content = "Casta, ayo lanjutkan!",
  ui_story_5034_50340501_70_dialog_content = "Diterima.",
  ui_story_5034_50340502_1_dialog_content = "Aku bisa merasakan Eclipsites di dekatnya... Mungkin mereka mengejar anak-anak di jalan ini?",
  ui_story_5034_50340502_2_dialog_content = "Sial, bukan jalan yang dipenuhi preman ini lagi...",
  ui_story_5034_50340502_3_dialog_content = "Tenang saja, mereka tidak akan menyentuhmu selama aku di sini.",
  ui_story_5034_50340502_4_dialog_content = "Sehat? Masih bisakah Anda merasakan Eclipsites, atau tahu ke arah mana mereka pergi?",
  ui_story_5034_50340502_5_dialog_content = "Aku tidak merasakan mereka lagi...",
  ui_story_5034_50340502_6_dialog_content = "Tapi jika mereka lewat sini, mungkin saja mereka dihabisi oleh preman jalanan ini, kan?",
  ui_story_5034_50340502_7_dialog_content = "Jadi apa yang harus kita lakukan sekarang? Itu satu-satunya petunjuk kami...",
  ui_story_5034_50340502_8_dialog_content = "Jangan khawatir, dengan semua orang ini, saya yakin seseorang pasti telah melihat mereka berdua.",
  ui_story_5034_50340502_9_dialog_content = "Mari kita berpisah dan bertanya-tanya.",
  ui_story_5034_50340502_10_dialog_content = "Baiklah…",
  ui_story_5034_50340502_11_dialog_content = "Aku tahu kamu masih merasa bersalah, tapi sekarang prioritas utama kita adalah menemukan anak-anak.",
  ui_story_5034_50340502_12_dialog_content = "Kamu benar. Kita harus bergegas jika ingin menyelamatkan mereka.",
  ui_story_5034_50340502_13_dialog_content = "Aku akan pergi bertanya-tanya di sana. Mari kita bertemu di sini setelah kita belajar lebih banyak.",
  ui_story_5034_50340502_14_dialog_content = "Kedengarannya bagus.",
  ui_story_5034_50340502_15_dialog_content = "Hah? Bukan kamu lagi!",
  ui_story_5034_50340502_16_dialog_content = "Astaga, kau seperti lalat menyebalkan yang tidak berhenti berdengung di kepalaku. Apa yang kamu lakukan di sini lagi?",
  ui_story_5034_50340502_17_dialog_content = "Ah, pria besar! Syukurlah kau masih di sini!",
  ui_story_5034_50340502_18_dialog_content = "Juga, bukankah aku sudah memberitahumu namaku? Nya-",
  ui_story_5034_50340502_19_dialog_content = "PlayerName, Baik? Saya tidak lupa, sekarang cepat dan katakan apa yang Anda inginkan!",
  ui_story_5034_50340502_20_dialog_content = "Apakah Anda ingat gadis kecil itu sebelumnya hari ini? Orang yang mencoba menjual kacamata hitam padamu?",
  ui_story_5034_50340502_21_dialog_content = "Pernahkah Anda melihatnya di sekitar sini?",
  ui_story_5034_50340502_22_dialog_content = "Apa, bocah kecil itu? Ya, aku melihatnya beberapa waktu lalu.",
  ui_story_5034_50340502_23_dialog_content = "Dia lari ke arah itu dengan beberapa anak kecil lainnya.",
  ui_story_5034_50340502_24_dialog_content = "Anda penyelamat, pria besar! Anda harus berpikir tentang membuka Lowongan Kerja Ganjil di sini di Euphoria, Anda tahu?",
  ui_story_5034_50340502_25_dialog_content = "Harus pergi sekarang! Terima kasih lagi!",
  ui_story_5034_50340502_26_dialog_content = "Apa? Hai-",
  ui_story_5034_50340502_27_dialog_content = "Dia pergi. punk sialan...",
  ui_story_5034_50340502_28_dialog_content = [[
*Membersihkan tenggorokan* 
<size=45>Jika kamu ingin tinggal di Euphoria, aku akan menerimamu sebagai adik kecilku!</size>]],
  ui_story_5034_50340502_29_dialog_content = "<size=45>Kedengarannya bagus untuk saya!</size>",
  ui_story_5034_50340502_30_dialog_content = "<size=45>Kecuali saya bisa menjadi yang terbesar!</size>",
  ui_story_5034_50340502_31_dialog_content = "Casta! Aku tahu ke mana mereka pergi!",
  ui_story_5034_50340502_32_dialog_content = "Bagus, kalau begitu mari kita pergi.",
  ui_story_5034_50340502_33_dialog_content = "Oke!",
  ui_story_5034_50340601_1_dialog_content = "Hmm? Apa ini...",
  ui_story_5034_50340601_2_dialog_content = "Tunggu, bagaimana dia bisa sejauh ini?",
  ui_story_5034_50340601_3_dialog_content = "Tidak terlalu terlambat. aku masih bisa...",
  ui_story_5034_50340601_4_dialog_content = "Tunggu dulu!",
  ui_story_5034_50340601_5_dialog_content = "Latan, Schewe, aku tidak akan membiarkan apapun terjadi pada kalian...",
  ui_story_5034_50340601_6_dialog_content = "<size=45>Sudah kubilang tunggu!!</size>",
  ui_story_5034_50340601_7_dialog_content = "Kita tidak punya waktu untuk disia-siakan, Casta! Jika kita tidak terburu-",
  ui_story_5034_50340601_8_dialog_content = "Bisakah kamu tenang sebentar? Lihatlah ini!",
  ui_story_5034_50340601_9_dialog_content = "Ini... Ini permen yang kuberikan pada mereka!",
  ui_story_5034_50340601_10_dialog_content = "Dan lihat! Ada lagi di sini!",
  ui_story_5034_50340601_11_dialog_content = "Sepertinya mereka menjatuhkan permen saat mereka berlari. Mungkin mereka meninggalkan jejak untuk kita ikuti?",
  ui_story_5034_50340601_12_dialog_content = "Yah, tidak masalah apakah mereka melakukannya dengan sengaja atau tidak.",
  ui_story_5034_50340601_13_dialog_content = "Selama kita mengikuti jejak permen, saya yakin kita akan menemukannya dalam waktu singkat.",
  ui_story_5034_50340601_14_dialog_content = "Anda benar sekali. Maaf karena kehilangan ketenangan saya.",
  ui_story_5034_50340601_15_dialog_content = "Untung Anda ada di sini untuk memperhatikan permen itu. Sekarang ayo cepat dan ikuti jejaknya!",
  ui_story_5034_50340601_16_dialog_content = "Sekarang tunggu sebentar. Lagipula, kita mungkin tidak perlu terburu-buru.",
  ui_story_5034_50340601_17_dialog_content = "Jika mereka memilih untuk berlari di jalan ini, maka saya hanya bisa memikirkan satu tempat yang akan mereka tuju.",
  ui_story_5034_50340601_18_dialog_content = "Apakah Anda mengatakan Anda sudah tahu di mana mereka berada?",
  ui_story_5034_50340601_19_dialog_content = "Gereja.",
  ui_story_5034_50340601_20_dialog_content = "Salah satu hal pertama yang kami ajarkan kepada anak-anak adalah langsung kembali ke gereja jika mereka menemukan diri mereka dalam masalah.",
  ui_story_5034_50340601_21_dialog_content = "Tapi meski begitu, ada kemungkinan mereka bertemu dengan Eclipsites di jalan. Kita belum bisa bersantai!",
  ui_story_5034_50340601_22_dialog_content = "Saya sama khawatirnya dengan keselamatan mereka seperti Anda, jika tidak lebih. Tapi saya tidak ingin Anda panik lebih dari yang sudah Anda miliki.",
  ui_story_5034_50340601_23_dialog_content = "Juga... Aku percaya padanya.",
  ui_story_5034_50340601_24_dialog_content = "Selama mereka berhasil sampai di dekat gereja, aku yakin dia tidak akan membiarkan sesuatu terjadi pada mereka.",
  ui_story_5034_50340601_25_dialog_content = "Sekarang mari kita bergerak. Kita akan kembali ke <color=#FFB400>gereja</color>.",
  ui_story_5034_50340601_26_dialog_content = "Mengapa pintu masuk gereja dikelilingi oleh Eclipsites? Kecuali penjaga toko mengejar mereka sampai ke sini?",
  ui_story_5034_50340601_27_dialog_content = "Ayo singkirkan mereka, Casta! Saya akan memandu Anda, dan Eclipsites ini tidak akan memiliki kesempatan melawan kita!",
  ui_story_5034_50340601_28_dialog_content = "Aku ingin, tapi...",
  ui_story_5034_50340601_29_dialog_content = "<color=#e8d9bb>Dor! Dor!</color>",
  ui_story_5034_50340601_30_dialog_content = "Saya pikir pertarungan ini milik orang lain sekarang.",
  ui_story_5034_50340601_31_dialog_content = "Apakah ini monster yang mengejar kalian berdua kembali ke sini?",
  ui_story_5034_50340601_32_dialog_content = "Tidak ada yang perlu dikhawatirkan lagi. Latan, Schewe, kamu aman sekarang.",
  ui_story_5034_50340601_33_dialog_content = "Pollux... Aku berjanji tidak akan kabur seperti itu lagi...",
  ui_story_5034_50340601_34_dialog_content = "A-Itu semua salahku...",
  ui_story_5034_50340601_35_dialog_content = "Anda sudah meminta maaf, bukan? Yang paling penting adalah kalian berdua kembali, aman dan sehat.",
  ui_story_5034_50340601_36_dialog_content = "Ayo sekarang... Tidak ada lagi air mata, oke?",
  ui_story_5034_50340601_37_dialog_content = "Itu Pollux! Dan anak-anak juga! Aku sangat senang mereka aman.",
  ui_story_5034_50340601_38_dialog_content = "Pikirkan Anda akhirnya bisa berhenti khawatir sekarang?",
  ui_story_5034_50340601_39_dialog_content = "Di sini, ini untuk Anda.",
  ui_story_5034_50340601_40_dialog_content = "Casta... Apakah kamu mengambil setiap permen yang kami lihat dalam perjalanan pulang?",
  ui_story_5034_50340601_41_dialog_content = "Anda tampak terlalu terburu-buru untuk memikirkan mereka.",
  ui_story_5034_50340601_42_dialog_content = "Bukankah Anda dan anak-anak bekerja keras untuk permen ini? Di sini, sekarang Anda dapat memberikannya kepada mereka.",
  ui_story_5034_50340601_43_dialog_content = "Terima kasih! Terima kasih banyak, Casta!",
  ui_story_5034_50340601_44_dialog_content = "Kalau saja kamu suka permen juga... Dengan begitu, aku bisa memberimu beberapa sebagai caraku mengucapkan terima kasih.",
  ui_story_5034_50340601_45_dialog_content = "Seperti aku pernah menikmati makan sesuatu yang kekanak-kanakan seperti permen.",
  ui_story_5034_50340601_46_dialog_content = "Sialan itu semua! Eclipsites yang tidak berotak ini tidak mengerti sepatah kata pun yang saya katakan!",
  ui_story_5034_50340601_47_dialog_content = "Bagaimana mereka bisa mengejar mereka berdua sampai ke sini?!",
  ui_story_5034_50340601_48_dialog_content = "Saya dapat menangani kehilangan uang dan barang dagangan, tetapi jika kedua wanita Darah Raven itu mengetahui hal ini...",
  ui_story_5034_50340601_49_dialog_content = "Grr... Graa...",
  ui_story_5034_50340601_50_dialog_content = "G-Menjauh dariku!",
  ui_story_5034_50340601_51_dialog_content = "Hei... Ini penjaga toko!",
  ui_story_5034_50340601_52_dialog_content = "Beraninya kau menunjukkan wajahmu di sekitar sini! Aku tidak akan membiarkanmu lolos kali ini!",
  ui_story_5034_50340601_53_dialog_content = "Graaah—",
  ui_story_5034_50340601_54_dialog_content = "Aaaaaahhh! Seseorang selamatkan aku!!",
  ui_story_5034_50340601_55_dialog_content = "Menyelamatkanmu? Kaulah yang pertama kali membawa semua Eclipsites ini ke sini! Anda membuat tempat tidur Anda, sekarang tidur di dalamnya!",
  ui_story_5034_50340601_56_dialog_content = "Aku... aku salah! Saya minta maaf! Saya mohon, tolong bantu saya!",
  ui_story_5034_50340601_57_dialog_content = "Aku akan melakukan apapun yang kamu mau, tolong jangan biarkan mereka memakanku hidup-hidup!",
  ui_story_5034_50340601_58_dialog_content = "Membalaskan dendam anak-anak akan terasa jauh lebih baik jika kita melakukannya sendiri, setuju kan?",
  ui_story_5034_50340601_59_dialog_content = "Anda benar sekali, Casta.",
  ui_story_5034_50340601_60_dialog_content = "Kubilang kita selamatkan dia dari Eclipsites. Dengan begitu, kita bisa membuatnya membayar kita kembali... dengan bunga.",
  ui_story_5034_50340602_1_dialog_content = "Adakah yang keberatan memberi tahu saya apa yang sedang terjadi di sini?",
  ui_story_5034_50340602_2_dialog_content = "Maaf, Pollux. Ini semua salahku.",
  ui_story_5034_50340602_3_dialog_content = "Anda lihat, apa yang terjadi adalah...",
  ui_story_5034_50340602_4_dialog_content = "<color=#e8d9bb>Jadi, saya menjelaskan semuanya kepada Pollux dari awal hingga akhir...</color>",
  ui_story_5034_50340602_5_dialog_content = "Baiklah, saya mengerti sekarang.",
  ui_story_5034_50340602_6_dialog_content = "Kami tidak asing satu sama lain. Saya yakin Anda tahu siapa yang bertanggung jawab di sini.",
  ui_story_5034_50340602_7_dialog_content = "P-Pollux... Sumpah, aku tidak bermaksud memimpin Eclipsites itu di sini! SAYA...",
  ui_story_5034_50340602_8_dialog_content = "Kecuali... kau pikir beberapa antek Eclipsite akan cukup untuk menjatuhkanku?",
  ui_story_5034_50340602_9_dialog_content = "T-Tidak! Sumpah bukan gitu!!",
  ui_story_5034_50340602_10_dialog_content = "Hanya saja aku tidak tahu kedua bocah itu—maksudku, dua pelanggan berharga itu berasal dari gerejamu...",
  ui_story_5034_50340602_11_dialog_content = "Jadi maksudmu adalah jika mereka hanya anak-anak biasa, kamu tidak akan kesulitan menipu mereka atau memberi mereka makan di Eclipsites? Itu saja?",
  ui_story_5034_50340602_12_dialog_content = "Aku bersumpah aku tidak akan pernah melakukannya lagi! Tolong, luangkan aku sekali ini saja!",
  ui_story_5034_50340602_13_dialog_content = "Aku akan melupakan semua hutang mereka!",
  ui_story_5034_50340602_14_dialog_content = "Oh, dan pembayaran mereka! Di sini, ini adalah pembayaran mereka untuk semua bantuan mereka! Jika itu tidak cukup, saya selalu dapat menambahkan lebih banyak!",
  ui_story_5034_50340602_15_dialog_content = "Silakan, Latan dan Schewe. Kalian berdua mendapatkannya, jadi itu milikmu untuk dikumpulkan.",
  ui_story_5034_50340602_16_dialog_content = "Aku akan pergi, Latan. Anda menunggu di sini, oke?",
  ui_story_5034_50340602_17_dialog_content = "Semuanya ada di sini, Pollux! Tidak ada satupun Nightium yang pendek!",
  ui_story_5034_50340602_18_dialog_content = "Ah, tapi tentu saja tidak cukup, ya? Apa lagi yang bisa saya tawarkan kepada Anda? Permen? Anda dapat memiliki semuanya!",
  ui_story_5034_50340602_19_dialog_content = "Tolong, biarkan saya kembali ke toko saya, dan saya berjanji akan mengirim seseorang untuk mengantarkannya tepat ke depan pintu Anda!",
  ui_story_5034_50340602_20_dialog_content = "Apa yang membuatmu berpikir kami akan mempercayaimu setelah semua ini?",
  ui_story_5034_50340602_21_dialog_content = "Dan bahkan jika Anda melakukan hal yang benar hari ini, siapa bilang Anda tidak akan mulai menipu orang lagi besok?",
  ui_story_5034_50340602_22_dialog_content = "Ooh, drama apa yang saya temukan. PlayerName memiliki titik.",
  ui_story_5034_50340602_23_dialog_content = "Euforia mungkin jauh dari jalan yang dilalui, tetapi bahkan jika semua barang Anda diimpor, harga Anda masih terlalu selangit, sama dengan monopoli.",
  ui_story_5034_50340602_24_dialog_content = "Terlebih lagi, barang yang Anda tagih untuk lengan dan kaki bahkan bukan masalah sebenarnya.",
  ui_story_5034_50340602_25_dialog_content = "Nekoyashiki, cukup munafik, bukan?",
  ui_story_5034_50340602_26_dialog_content = "Bukankah ini cara Anda menghasilkan uang juga? Satu-satunya perbedaan adalah Anda menjual informasi dan saya menjual barang dagangan.",
  ui_story_5034_50340602_27_dialog_content = "Anda tidak merasa bersalah tentang semua ini sama sekali, kan?!",
  ui_story_5034_50340602_28_dialog_content = "T-Bukankah aku sudah setuju untuk memberimu uang dan permen sebagai ganti keselamatanku?!",
  ui_story_5034_50340602_29_dialog_content = "Apa lagi yang kamu inginkan dariku?!",
  ui_story_5034_50340602_30_dialog_content = "Nah, karena Anda bertanya ... Saya sebenarnya punya ide. Jika Pollux setuju, maka kami akan mengampuni Anda.",
  ui_story_5034_50340602_31_dialog_content = "Mari kita dengar ide Anda, kalau begitu.",
  ui_story_5034_50340602_32_dialog_content = "Kami tidak ingin uang kotor Anda. Anda dapat menyimpan semuanya untuk diri sendiri.",
  ui_story_5034_50340602_33_dialog_content = "Tetapi Anda harus menyerahkan toko Anda dan membiarkan Nekoyashiki mengambil alih sebagai pemilik barunya.",
  ui_story_5034_50340602_34_dialog_content = "Karena kami tidak dapat menjamin bahwa Anda akan mengubah cara Anda, paling tidak yang dapat kami lakukan adalah mengambil toko Anda dan menyerahkannya kepada seseorang yang tidak akan bergantung pada trik semacam ini untuk menghasilkan uang.",
  ui_story_5034_50340602_35_dialog_content = "Lagi pula, saya yakin Anda punya cukup uang untuk keluar kota dan mencoba peruntungan di Umbraton, bukan?",
  ui_story_5034_50340602_36_dialog_content = "Saya yakin para pedagang di sana akan dengan senang hati menunjukkan kepada Anda cara <color=#FFB400>berbisnis dengan cara yang benar</color>.",
  ui_story_5034_50340602_37_dialog_content = "Tapi mengambil toko saya terlalu banyak, bukan begitu...?",
  ui_story_5034_50340602_38_dialog_content = "Saya pikir Anda mengatakan Anda bersedia melakukan apa saja? Atau apakah Anda akan kembali pada kata-kata Anda begitu cepat?",
  ui_story_5034_50340602_39_dialog_content = "Argh... Baik. Toko adalah milik Anda sepenuhnya.",
  ui_story_5034_50340602_40_dialog_content = "Sekarang bisakah Anda membiarkan saya pergi?",
  ui_story_5034_50340602_41_dialog_content = "Jangan biarkan kami memergoki Anda melakukan hal semacam ini lagi, atau Anda mungkin tidak seberuntung itu di lain waktu. Memahami?",
  ui_story_5034_50340602_42_dialog_content = "Oh, dan berhati-hatilah dalam perjalanan kembali. Beberapa \"hewan peliharaan\" Anda mungkin masih berkeliaran di luar sana.",
  ui_story_5034_50340602_43_dialog_content = "… Hmm.",
  ui_story_5034_50340602_44_dialog_content = "Anda tampak sangat senang tentang PlayerNamekondisi.",
  ui_story_5034_50340602_45_dialog_content = "Anda telah merencanakan ini, bukan ...",
  ui_story_5034_50340602_46_dialog_content = "Tidak ada yang melewati Anda sama sekali.",
  ui_story_5034_50340602_47_dialog_content = "Tapi saya tidak berharap anak-anak akan terlibat juga. Itu salahku karena ceroboh, dan aku minta maaf.",
  ui_story_5034_50340602_48_dialog_content = "Aku bergegas kembali begitu mendengar apa yang terjadi. Untung dia cukup pintar, kalau tidak, anak-anak mungkin akan mendapat lebih banyak masalah.",
  ui_story_5034_50340602_49_dialog_content = "Di mana dia?",
  ui_story_5034_50340603_1_dialog_content = "Tuan Navigator! Saya sangat senang Eclipsites tidak melahap Anda dan memuntahkan tulang Anda!",
  ui_story_5034_50340603_2_dialog_content = "Tentu saja tidak... Aku tahu kau tidak bermaksud apa-apa, tapi kau harus benar-benar memilih kata-katamu dengan lebih hati-hati, Latan.",
  ui_story_5034_50340603_3_dialog_content = "Pokoknya, lihatlah apa yang saya miliki di sini!",
  ui_story_5034_50340603_4_dialog_content = "Ini permen yang kutinggalkan!",
  ui_story_5034_50340603_5_dialog_content = "Saya tahu Anda akan menemukannya, Tn. Navigator!",
  ui_story_5034_50340603_6_dialog_content = "Anda yang terhebat, Tn. Navigator!",
  ui_story_5034_50340603_7_dialog_content = "Bukan hanya aku, kau tahu? Berkat kalian dan pemikiran cepat kalian, saya bisa mengikuti jejak kalian dan menemukan kalian.",
  ui_story_5034_50340603_8_dialog_content = "Namun, saya tidak pernah berharap Anda akan mengambil semuanya dan mengembalikannya kepada kami, Tn. Navigator...",
  ui_story_5034_50340603_9_dialog_content = "Yah, mereka sangat berarti bagimu, bukan? Ini, bawa mereka.",
  ui_story_5034_50340603_10_dialog_content = "Juga, Casta yang mengambil permen itu, bukan aku. Jika ada yang pantas menerima ucapan terima kasih Anda, itu dia.",
  ui_story_5034_50340603_11_dialog_content = "Tapi Casta benci permen, atau apapun yang manis dalam hal ini... Dia hanya suka yang pahit.",
  ui_story_5034_50340603_12_dialog_content = "Ngomong-ngomong, bukan berarti kita lupa memberi Casta hadiah.",
  ui_story_5034_50340603_13_dialog_content = "Apakah begitu? Aku masih harus berterima kasih padanya karena telah membantuku hari ini.",
  ui_story_5034_50340603_14_dialog_content = "Kecuali aku tidak tahu di mana aku harus menemukan sesuatu yang pahit untuknya...",
  ui_story_5034_50340603_15_dialog_content = "Jadi apa yang kalian berdua dapatkan? Mungkin saya bisa meminjam inspirasi?",
  ui_story_5034_50340603_16_dialog_content = "Anu…",
  ui_story_5034_50340603_17_dialog_content = "Saya kira tidak apa-apa untuk memberitahu Anda, karena Anda menyelamatkan kami hari ini. Tapi ini kejutan, jadi jangan beri tahu siapa pun!",
  ui_story_5034_50340603_18_dialog_content = "Rencana kami adalah menunggu sampai dia tidak melihat... dan kemudian mengejutkannya dengan pelukan beruang besar!",
  ui_story_5034_50340603_19_dialog_content = "Meskipun dia selalu mengeluh bahwa itu terlalu panas ketika kita memeluknya ...",
  ui_story_5034_50340603_20_dialog_content = "Saya telah melihatnya tersenyum pada dirinya sendiri setelah setiap pelukan!",
  ui_story_5034_50340603_21_dialog_content = "Jika Anda ingin berterima kasih padanya juga, Tuan Navigator... mengapa tidak memeluknya?",
  ui_story_5034_50340603_22_dialog_content = "Er... Kupikir aku akan berpura-pura tidak mendengar apa-apa.",
  ui_story_5034_50340603_23_dialog_content = "Apakah Anda pikir Pollux akan menyukai permen kami juga, Tn. Navigator?",
  ui_story_5034_50340603_24_dialog_content = "Kami menyebabkan begitu banyak masalah karena beberapa permen ...",
  ui_story_5034_50340603_25_dialog_content = "Tentu saja. Saya yakin dia akan sangat menikmatinya.",
  ui_story_5034_50340603_26_dialog_content = "Jika kalian berbagi hal-hal favorit Anda dengannya, dia pasti akan menghargai gerakan itu.",
  ui_story_5034_50340603_27_dialog_content = "Selain itu, dia tidak akan pernah marah padamu atas apa yang terjadi hari ini.",
  ui_story_5034_50340603_28_dialog_content = "Yang paling penting baginya, dan bagi kami, adalah Anda berdua aman dan sehat.",
  ui_story_5034_50340603_29_dialog_content = "Coba pikirkan—bukankah dia lega ketika kalian berdua berhasil kembali ke gereja dengan selamat?",
  ui_story_5034_50340603_30_dialog_content = "Jika ada, kalian harus mengkhawatirkanku, dan apa yang akan dia lakukan padaku karena menyebabkan semua masalah ini sejak awal...",
  ui_story_5034_50340603_31_dialog_content = "Ini, Tn. Navigator. Ambil setengah dari permen saya.",
  ui_story_5034_50340603_32_dialog_content = "Hah?",
  ui_story_5034_50340603_33_dialog_content = "Jika kamu memberikannya kepada Pollux, dia juga tidak akan marah padamu!",
  ui_story_5034_50340603_34_dialog_content = "K-Kalau begitu ambil setengah dari permenku juga, Tuan Navigator!",
  ui_story_5034_50340603_35_dialog_content = "Itu hadiah terima kasih untukmu, Tuan Navigator!",
  ui_story_5034_50340603_36_dialog_content = "Ha ha ha! Terima kasih banyak, teman-teman. Aku hanya akan mengambil satu potong dari kalian masing-masing, oke?",
  ui_story_5034_50340603_37_dialog_content = "Saya akan menghargai permen yang Anda berikan kepada saya selamanya!",
  ui_story_5034_50340603_38_dialog_content = "Schewe! Latan! PlayerName!",
  ui_story_5034_50340603_39_dialog_content = "Makan malam sudah siap, jadi cepatlah, atau tidak akan ada yang tersisa untukmu!",
  ui_story_5034_50340603_40_dialog_content = "Ayo, kalian berdua. Ayo makan enak dengan susah payah!",
  ui_story_5034_50340603_41_dialog_content = "Oke!"
}
return config
